function v247Create(source=''){
 const d=v247Draft(source),state=v247State(source);
 try{
  const name=d.name.trim(),rule=d.rule.trim(),type=d.type;if(!name||name.length>60)throw prototypeGlobal.Error('请填写 1～60 个字的变量名称。');
  if(!['number','text'].includes(type))throw prototypeGlobal.Error('请选择数字或文字。');
  if(source&&!v152Object(source))throw prototypeGlobal.Error('当前控件已不存在，请返回后重新选择。');
  if(source&&v236Numeric(source,state.link)&&type==='text')throw prototypeGlobal.Error('当前控件需要数字变量。');
  const initial=type==='text'?d.initial:prototypeGlobal.Number(d.initial),min=type==='text'||!prototypeGlobal.String(d.min).trim()?null:prototypeGlobal.Number(d.min),max=type==='text'||!prototypeGlobal.String(d.max).trim()?null:prototypeGlobal.Number(d.max);
  if(type==='number'&&(!prototypeGlobal.String(d.initial).trim()||![initial,...[min,max].filter(x=>x!==null)].every(prototypeGlobal.Number.isFinite)||min!==null&&max!==null&&min>=max||min!==null&&initial<min||max!==null&&initial>max))throw prototypeGlobal.Error('请填写有效的初始值与范围，初始值须在范围内。');
  if(d.ai&&!rule)throw prototypeGlobal.Error('请填写更新规则，或关闭“AI 随剧情更新”。');
  const f={id:'field247-'+nextId++,name,owner:d.owner.trim()||'本作品',type,initial,enabled:true};
  if(type==='number'){f.unit=d.unit.trim();if(min!==null)f.min=min;if(max!==null)f.max=max;}
  const cfg=njClone(v222AIConfig());cfg.fields??={};cfg.fields[f.id]={enabled:!!d.ai,rule,format238:true};
  sceneRemember();c3Defs().push(f);if(source)v236Link(source,f.id,state.link);data['AI更新配置222']=cfg;
  state.field=f.id;state.creation247=null;state.error=false;state.message='变量已创建，名称、初始值和更新规则都可以继续修改。';
  if(source){state.picker=false;state.newVariable=false;state.rule='';}else state.creating247=false;
  v135UI().requests.clear();njDirty();if(source)v236Refresh(true);else v229Render();
 }catch(error){d.error=error.message;v247Render(source);q('.v247-error')?.scrollIntoView({block:'nearest'});}
}
