function v243DescribeAction(a){
 const type=v240Type(a),target=v152Object(a.target)?.label||a.target||'目标',literal=a.value?.kind==='literal',value=a.value?.value;
 if(!literal)return v222ActionName(a)+'（沿用已配置的内容来源）。';
 const asset=nj.assets.find(x=>prototypeGlobal.String(x.key)===prototypeGlobal.String(value))?.name||prototypeGlobal.String(value??''),name='「'+target+'」';
 if(type==='portrait')return '把'+name+'的立绘换成「'+asset+'」。';
 if(type==='background')return '把'+name+'的背景换成「'+asset+'」。';
 if(type==='image')return a.member==='image240'?'在作品画面上展示「'+asset+'」图片，'+(a.duration??4)+' 秒后自动收起。':'将'+name+'的图片设置为「'+asset+'」。';
 if(type==='sequence')return a.member==='sequence240'?'叠加播放「'+asset+'」序列帧，'+(a.duration??4)+' 秒后结束。':'播放'+name+'的序列帧。';
 if(type==='panel')return '打开'+name+'界面。';
 if(type==='cg')return '全屏展示「'+asset+'」CG 图片，点击继续后返回。';
 if(type==='audio')return '播放「'+(a.member==='play'?'作品背景音乐':music.find(m=>prototypeGlobal.String(m.id)===prototypeGlobal.String(value))?.name||value)+'」。';
 if(type==='color')return '把'+name+'的字体颜色改为 '+value+'。';
 if(type==='size')return '把'+name+'的字号改为 '+value+'。';
 return v222ActionName(a)+(value!==prototypeGlobal.undefined&&value!==''?'：'+prototypeGlobal.String(value):'')+'。';
}
function v243Description(rule){return (rule.actions||[]).map(v243DescribeAction).join('\n');}
function v243Text(rule){return typeof rule.effectText243==='string'?rule.effectText243:v243Description(rule);}
function v243Pending(rule){return typeof rule.effectText243==='string'&&rule.effectText243.trim()!==v243Description(rule).trim();}
function v243Meta(rule){return v243Pending(rule)?'效果描述 · 待配置执行':(rule.actions||[]).length+' 项已配置效果';}
