function v243Install(){
 if(v243Install.done)return;v243Install.done=true;
 prototypeGlobal.window.addEventListener('input',e=>{const field=e.target;if(!field.matches?.('[data-v243-text]')||!r.contains(field))return;const rule=v222Current();if(!rule)return;rule.effectText243=field.value;v243RenderWriting(field.closest('.v222'),rule);},true);
 prototypeGlobal.window.addEventListener('click',e=>{
  const b=e.target.closest?.('[data-v243-example],[data-v243-group],[data-v243-all],[data-v243-from-settings],[data-v243-save-description]');if(!b||!r.contains(b))return;e.preventDefault();e.stopImmediatePropagation();const rule=v222Current(),host=b.closest('.v222');if(!rule||!host)return;const state=v243State(rule);
  if(b.hasAttribute('data-v243-group')||b.hasAttribute('data-v243-all')){state.group=b.dataset.v243Group||state.group;state.all=b.hasAttribute('data-v243-all');host.querySelector('[data-v243-examples]').innerHTML=v243ExampleList(rule);return;}
  if(b.hasAttribute('data-v243-save-description')){if(!v243Text(rule).trim()){toast('先填写希望发生的效果。','warning');return;}if(v236Host())v236CommitRule('draft');else v222Save(false);return;}
  if(b.hasAttribute('data-v243-from-settings')){delete rule.effectText243;v243SetText(host,rule,v243Description(rule),true);state.message='已填入现有配置的描述。';}
  else {const ex=v243Examples().find(x=>x.id===b.dataset.v243Example);if(ex)v245ApplyExample(ex);return;}
  const feedback=host.querySelector('[data-v243-example-feedback]');if(feedback)feedback.textContent=state.message;
 },true);
}

