/* Contain-size portraits have a tight interactive rectangle instead of a
   wide invisible hit area. Existing visual size and alignment are preserved. */
function v183ContainBox(p,ratio,width,height,alignX=50,alignY=50){
 if(!(ratio>0&&width>0&&height>0))return p;
 const boxWidth=p.w/100*width,boxHeight=p.h,scale=prototypeGlobal.Math.min(boxWidth/ratio,boxHeight),w=scale*ratio;
 if(!(w>0&&scale>0))return p;
 return {...p,x:p.x+(boxWidth-w)/width*prototypeGlobal.Math.max(0,prototypeGlobal.Math.min(100,alignX))/100*100,y:p.y+(boxHeight-scale)/height*prototypeGlobal.Math.max(0,prototypeGlobal.Math.min(100,alignY))/100*100,w:w/width*100,h:scale,fixed:true};
}
