 if(!current||!tree)return;
 const buttons=[...tree.querySelectorAll('button[data-wb-select],button[data-wb-group]')],index=buttons.indexOf(current);
 let next;
 if(e.key==='ArrowDown')next=buttons[prototypeGlobal.Math.min(buttons.length-1,index+1)];
 else if(e.key==='ArrowUp')next=buttons[prototypeGlobal.Math.max(0,index-1)];
