const field=(n,m=false,ph='')=>`<label class="field"><span>${n}</span>${m?`<textarea data-field="${n}" placeholder="${esc(ph)}">${esc(data[n]||'')}</textarea>`:`<input data-field="${n}" value="${esc(data[n]||'')}" placeholder="${esc(ph)}">`}</label>`;
const select=(n,opts)=>`<label class="field"><span>${n}</span><select data-field="${n}">${opts.map(v=>`<option ${(data[n]??opts[0])===v?'selected':''}>${v}</option>`).join('')}</select></label>`;
const check=(n)=>`<label class="check"><input type="checkbox" data-check="${n}" ${data[n]?'checked':''}>${n}</label>`;
const upload=(n,ratio='16/9',max='100%')=>`<div class="field"><span>${n}</span><label class="upload" style="aspect-ratio:${ratio};max-width:${max}">${images[n]?`<img src="${images[n]}" alt="${n}">`:`<span class="uploadtext"><b>＋</b>${ratio.replace('/',':')}</span>`}<input type="file" data-image="${n}" accept="image/*" aria-label="上传${n}"></label></div>`;
function njBaseToast(t){const el=q('#ps-toast');prototypeGlobal.clearTimeout(toast.timer);el.textContent=t;el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.classList.add('wb-toast-visible');toast.timer=prototypeGlobal.setTimeout(()=>{el.classList.remove('wb-toast-visible');el.textContent='';},3500);}function activeZone(){return zones.find(z=>z.id===zoneId)||zones[0]}
const selectedTags=[];let tagCategory='全部',tagLibraryExpanded=false,tagSearch='';
const tagGroups={'题材':['纯爱','甜文','虐文','救赎','校园','冒险','悬疑','日常','养成'],'世界观':['现代都市','开放世界','赛博朋克','末日生存','修仙','西幻','架空历史','星际'],'性癖':['制服','丝袜','主导','臣服'],'玩法':['沉浸式','自由探索','多结局','单人卡','多角色','剧情向','低消耗','长篇','短篇'],'关系':['BG','BL','GL','自定义角色']};
const bgm={url:'',file:''};const baseAudio=new prototypeGlobal.Audio(),eventAudio=new prototypeGlobal.Audio();baseAudio.loop=true;let activeTrack=null,audioSession=false,playGeneration=0,audioStatus='尚未开始试听';
function tagButtons(tags){return tags.map(t=>`<button data-tag-value="${esc(t)}" aria-pressed="${selectedTags.includes(t)}" class="${selectedTags.includes(t)?'on':''}">${esc(t)}${selectedTags.includes(t)?' ✓':''}</button>`).join('')||'<span class="muted">暂无匹配标签</span>';}
function tagBlock(){const all=prototypeGlobal.Object.values(tagGroups).flat(),matches=all.filter(t=>t.toLowerCase().includes(tagSearch.trim().toLowerCase()));return`<section class="tag-section"><div class="row tag-heading"><strong>作品标签</strong><button data-tags="recommend">✦ AI 推荐标签</button></div><div class="tag-create-row"><input id="ps-tag-create" aria-label="搜索或者创建标签" placeholder="搜索或者创建" value="${esc(tagSearch)}"><button class="solid" data-tags="create">创建新标签</button></div><h4>已选择标签（${selectedTags.length}/8）</h4><div class="tag-selected-list">${selectedTags.length?selectedTags.map(t=>`<button class="on" data-tag-value="${esc(t)}" aria-label="移除标签 ${esc(t)}">${esc(t)} ×</button>`).join(''):'<span class="muted">暂无</span>'}</div><h4>全部标签（${all.length}）</h4><div id="ps-tag-matches" class="inline-tags">${tagButtons(matches)}</div><button class="library-expand" data-tags="expand" aria-expanded="${tagLibraryExpanded}" aria-controls="ps-full-tag-library">${tagLibraryExpanded?'收起完整标签库 ↑':'查看完整标签库 ↓'}</button>${tagLibraryExpanded?`<div id="ps-full-tag-library"><div class="inline-categories" role="tablist" aria-label="标签分类">${['全部',...prototypeGlobal.Object.keys(tagGroups)].map((c,i)=>`<button id="ps-tag-tab-${i}" role="tab" aria-controls="ps-tag-category-panel" aria-selected="${tagCategory===c}" data-tag-category="${esc(c)}" class="${tagCategory===c?'on':''}">${esc(c)}</button>`).join('')}</div><div id="ps-tag-category-panel" role="tabpanel" aria-labelledby="ps-tag-tab-${['全部',...prototypeGlobal.Object.keys(tagGroups)].indexOf(tagCategory)}">${(tagCategory==='全部'?prototypeGlobal.Object.entries(tagGroups):[[tagCategory,tagGroups[tagCategory]]]).map(([c,tags])=>`<div class="tag-category-section"><h4>${esc(c)}</h4><div class="inline-tags expanded">${tagButtons(tags)}</div></div>`).join('')}</div></div>`:''}</section>`;}
r.addEventListener('keydown',e=>{if(e.target.id==='ps-tag-create'&&e.key==='Enter'&&!e.isComposing){e.preventDefault();q('[data-tags="create"]').click();}});
function homeCard(){const name=esc(data['作品名称']||'作品名称'),intro=esc(data['简介']||'填写作品简介，展示你的故事与世界。'),tags=selectedTags.map(t=>`<span>${esc(t)}</span>`).join(''),cover=images['作品封面'];if(target==='mobile')return`<div class="mobile-home" ${cover?'style="background-image:url('+cover+')"':''}><div class="mobile-home-nav"><span>☰</span><span>关注</span><strong>推荐</strong><span>最新</span><span>⌕</span></div>${!cover?'<div class="mobile-cover-empty">作品封面预览</div>':''}<div class="mobile-home-story"><h2>${name}</h2><div class="mobile-home-meta"><span class="mobile-heat">🔥 0</span><div class="mobile-home-tags">${tags}</div><span class="mobile-author">● 创作者</span></div><details class="mobile-home-intro"><summary>${intro}<em>查看详情</em></summary><p>${intro}</p></details><div class="mobile-home-stats"><span>▱ 月票 0</span><span>▤ 评论 0</span><span>◉ 0 轮</span></div><button data-preview-start class="mobile-start">开始聊天</button></div><div class="mobile-home-bottom"><span class="active">⌂<small>首页</small></span><span>◎<small>发现</small></span><span class="flower">✿</span><span>▤<small>消息</small></span><span>♙<small>我的</small></span></div></div>`;return`<div class="home-preview"><div class="home-top"><strong>桃花岛</strong><span>关注　 推荐　 最新</span></div><div class="home-card-grid"><article class="home-work-card"><div class="home-cover">${cover?`<img src="${cover}" alt="作品封面">`:'<span>作品封面</span>'}<span class="home-heat" aria-label="热度 0">🔥 0</span></div><div class="home-card-body"><h4>${name}</h4><p>${intro}</p><div class="home-card-tags">${tags}</div></div><footer class="home-card-footer"><span><b>创</b> 当前创作者</span><span aria-label="月票 0">▰ 0</span></footer></article></div><p class="muted">首页预览 · 未发布作品数据为 0</p></div>`;}
function audioNotice(t){audioStatus=t;const el=q('#ps-audio-status');if(el)el.textContent=t;}
async function resumeBase(){if(!audioSession||!bgm.url)return;if(baseAudio.getAttribute('src')!==bgm.url)baseAudio.src=bgm.url;v151ApplyVolume();const stamp=playGeneration;try{await baseAudio.play();if(stamp!==playGeneration)return;audioNotice('常规 BGM 播放中'+(baseAudio.currentTime>0?' · 从暂停处继续':''));}catch(e){if(stamp===playGeneration)audioNotice('请点击“开始试听”允许播放音频。');}}
function endTrigger(){++playGeneration;eventAudio.pause();eventAudio.currentTime=0;activeTrack=null;if(audioSession)resumeBase();else audioNotice('已停止试听');}
function stopAudio(){++playGeneration;audioSession=false;activeTrack=null;baseAudio.pause();eventAudio.pause();baseAudio.currentTime=0;eventAudio.currentTime=0;audioNotice('已停止试听');}
eventAudio.addEventListener('ended',endTrigger);eventAudio.addEventListener('error',()=>{if(activeTrack){audioNotice('触发音轨无法播放，恢复常规 BGM');endTrigger();}});
async function triggerTrack(m){if(!m.url){audioNotice('命中“'+(m.name||'未命名音轨')+'”，但尚未上传音频，继续播放 BGM。');return;}audioSession=true;const stamp=++playGeneration;baseAudio.pause();eventAudio.pause();activeTrack=m.id;eventAudio.src=m.url;eventAudio.loop=!!m.loop;v151TrackGain=m.volume??.8;v151ApplyVolume();audioNotice('已触发“'+(m.name||'未命名音轨')+'” · 常规 BGM 已暂停');try{await eventAudio.play();if(stamp!==playGeneration)return;}catch(e){if(stamp===playGeneration){activeTrack=null;audioNotice('触发音轨播放失败');resumeBase();}}}
function v2BasenewMusicUI(){return`<div class="entrybox"><header><strong>背景音乐（BGM）</strong><span class="muted">正常游玩时播放</span></header><label class="field"><span>常规背景音乐</span><input type="file" accept="audio/*" data-bgm-upload><small>${esc(bgm.file||'未选择文件')}</small></label></div><div class="sectiontitle"><span>触发式音轨</span><button data-music="add">＋ 添加触发轨</button></div>${music.map((m,i)=>`<div class="entrybox"><header><span>触发音轨 ${i+1}</span><button data-music="delete" data-track-id="${m.id}">删除</button></header><label class="field"><span>轨道名称</span><input data-track-prop="name" data-track-id="${m.id}" value="${esc(m.name)}" placeholder="例如：战斗曲"></label><label class="field"><span>音频文件</span><input type="file" accept="audio/*" data-track-upload="${m.id}"><small>${esc(m.file||'未选择文件')}</small></label><label class="field"><span>触发关键词（逗号分隔）</span><input data-track-prop="key" data-track-id="${m.id}" value="${esc(m.key)}" placeholder="例如：战斗、拔剑"></label><div class="row"><label class="row">匹配<select data-track-prop="match" data-track-id="${m.id}" style="width:auto"><option ${m.match==='任一'?'selected':''}>任一</option><option ${m.match==='全部'?'selected':''}>全部</option></select></label><label class="check"><input type="checkbox" data-track-prop="loop" data-track-id="${m.id}" ${m.loop?'checked':''}>循环</label><label class="check"><input type="checkbox" data-track-prop="enabled" data-track-id="${m.id}" ${m.enabled?'checked':''}>启用</label></div><label class="field"><span>音量</span><input type="range" min="0" max="1" step="0.05" data-track-prop="volume" data-track-id="${m.id}" value="${m.volume??.8}"></label>${m.loop?'<p class="muted">循环开启后不会自然结束；试听时点击“结束触发音轨”恢复 BGM。</p>':''}</div>`).join('')||'<div class="empty">添加音轨，配置特定场景的关键词。</div>'}<div class="entrybox"><header>播放逻辑试听</header><p class="muted">触发提示 → 暂停 BGM → 播放触发音轨 → 播放结束后从暂停处继续 BGM。</p><div class="row"><button data-music="start">开始试听</button><button data-music="stop">停止试听</button></div><label class="field" style="margin-top:12px"><span>模拟剧情文本</span><input id="ps-trigger-text" placeholder="输入包含关键词的场景文本"></label><div class="row"><button data-music="trigger">模拟剧情触发</button><button data-music="end">结束触发音轨</button></div><p id="ps-audio-status" class="musicresult" aria-live="polite">${esc(audioStatus)}</p></div>`;}
r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tags==='recommend')toast('AI 推荐标签入口演示，尚未连接 AI。');if(b.dataset.tags==='create'||b.dataset.tags==='expand'||b.dataset.tagCategory||b.dataset.tagValue){const pos=q('#ps-editor .body').scrollTop;if(b.dataset.tags==='create'){const name=tagSearch.trim();if(!name){toast('请先输入标签名称。');return;}if(selectedTags.includes(name)){toast('已选择这个标签。');return;}if(selectedTags.length>=8){toast('最多选择 8 个标签。');return;}if(!prototypeGlobal.Object.values(tagGroups).flat().includes(name)){if(!tagGroups['自定义'])tagGroups['自定义']=[];tagGroups['自定义'].push(name);}selectedTags.push(name);data['标签']=selectedTags.join('、');tagSearch='';}if(b.dataset.tags==='expand')tagLibraryExpanded=!tagLibraryExpanded;if(b.dataset.tagCategory)tagCategory=b.dataset.tagCategory;if(b.dataset.tagValue){const t=b.dataset.tagValue,i=selectedTags.indexOf(t);if(i>=0)selectedTags.splice(i,1);else if(selectedTags.length<8)selectedTags.push(t);else toast('最多选择 8 个标签。');data['标签']=selectedTags.join('、');}editor();preview();q('#ps-editor .body').scrollTop=pos;}switch(b.dataset.music){case'add':music.push({id:nextId++,name:'',key:'',enabled:true,loop:false,match:'任一',volume:.8,url:'',file:''});editor();break;case'delete':{const id=+b.dataset.trackId;if(activeTrack===id)endTrigger();const idx=music.findIndex(m=>m.id===id);if(idx>=0)music.splice(idx,1);editor();break;}case'start':if(!bgm.url){audioNotice('请先上传常规 BGM。');break;}audioSession=true;if(activeTrack===null)resumeBase();break;case'stop':stopAudio();break;case'end':if(activeTrack!==null)endTrigger();break;case'trigger':{const text=q('#ps-trigger-text').value;const m=music.find(m=>{const keys=m.key.split(/[,，\n]/).map(k=>k.trim()).filter(prototypeGlobal.Boolean);return m.enabled&&keys.length&&(m.match==='全部'?keys.every(k=>text.includes(k)):keys.some(k=>text.includes(k)));});if(m)triggerTrack(m);else audioNotice('未命中启用的触发音轨');break;}}});
r.addEventListener('input',e=>{const t=e.target;if(t.id==='ps-tag-create'){tagSearch=t.value;q('#ps-tag-matches').innerHTML=tagButtons(prototypeGlobal.Object.values(tagGroups).flat().filter(x=>x.toLowerCase().includes(tagSearch.trim().toLowerCase())));}if(t.dataset.trackProp){const m=music.find(m=>m.id===+t.dataset.trackId);if(!m)return;const p=t.dataset.trackProp;m[p]=t.type==='checkbox'?t.checked:p==='volume'?+t.value:t.value;if(activeTrack===m.id){v151TrackGain=m.volume;v151ApplyVolume();eventAudio.loop=m.loop;if(!m.enabled)endTrigger();}}});
