r.addEventListener('keydown',e=>{const b=e.target.closest('[data-zone-grip]');if(!b||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const id=b.dataset.zoneGrip,i=zones.findIndex(z=>prototypeGlobal.String(z.id)===id),next=zones[i+(e.key==='ArrowUp'?-1:1)];if(next&&zoneMove(id,next.id)){zoneRefreshList();preview();q(`[data-zone-grip="${id}"]`)?.focus();toast('分区顺序已更新。');}});
