function svLegacyZoneUI(){const z=activeZone();return`<div class="zone-workspace"><div class="zone-directory"><div class="zone-list-head"><span>分区列表</span></div><p class="muted zone-hint">按住任意分区拖动排序</p><div id="zone-list">${zoneRows()}</div><button class="zone-add-bottom" data-act="zone-new">＋ 添加新的分区</button></div><div class="zone-detail"><div id="ps-newzone" hidden class="entrybox"><label class="field"><span>自定义状态栏名称</span><input id="ps-newzone-name" placeholder="例如：主角信息、任务进度"></label><button data-act="zone-create">新增状态栏</button></div>${z?`<div class="wb-entry-frame"><header class="zone-detail-head"><strong>${esc(z.name)}</strong><label class="check"><input class="ps-toggle" type="checkbox" data-zone-prop="enabled" ${z.enabled?'checked':''}>启用</label><button data-act="zone-delete" aria-label="删除分区">删除</button></header><label class="field"><span>分区名称</span><input data-zone-prop="name" value="${esc(z.name)}"></label>${z.id===1?`<label class="check zone-visible"><input class="ps-toggle" type="checkbox" data-zone-prop="showInBody" ${z.showInBody?'checked':''}>在正文展示</label>`:''}<div class="grid2"><label class="field"><span>默认开合</span><select data-zone-prop="fold"><option ${z.fold==='展开'?'selected':''}>展开</option><option ${z.fold==='收起'?'selected':''}>收起</option></select></label></div>${presentationUI(z)}${z.fields?statusFieldsEditor(z):''}<div class="rc-zone-editor">${rcEditor("zone:"+z.id,z)}<textarea data-zone-prop="text" hidden aria-hidden="true">${esc(z.text)}</textarea></div>${z.id===3?`<label class="field"><span>剧情配图</span><input type="file" accept="image/*" data-image="剧情配图"></label>`:''}</div>`:'<p class="muted">点击 ＋ 添加分区。</p>'}</div></div>`;}
