function zoneContent(z){if(z.richContent&&z.id===2){const token='__RICH_CONTENT_VALUE__';return zoneContent({...z,richContent:prototypeGlobal.undefined,text:token}).replace(token,rcRender(z.richContent));}if(z.fields)return statusFieldPreview(z);const open=z.fold==='展开'?'open':'';if(z.kind==='status')return`<details class="reply-fold custom-status" ${open}><summary>${esc(z.name)}</summary><p>${esc(z.text||'填写状态栏内容后在此展示。')}</p></details>`;if(z.id===1&&!z.showInBody)return'';if(z.id===2){const family=data['正文字体']||'继承全局',font=family==='继承全局'?data['字体']:family;const body=(z.text||openings[0]?.text)?`<p>${esc(z.text||openings[0].text)}</p>`:`<p>雨停了，窗外传来轻轻的叩门声。书房里只亮着一盏灯，桌上的旧地图被摊开，边角压着一枚褪色的书签。</p><p class="zone-dialogue">“你终于来了。关于旧城的事，也许你应该先看看这个。”</p><p class="zone-action">他抬起头，将手中的信封轻轻推到桌边。</p>`;return`<div class="reply-prose" style="font-size:${zoneNumber('正文字号',data['字号']||16,12,48)}px;letter-spacing:${zoneNumber('正文字间距',0,-1,10)}px;line-height:${zoneNumber('正文行间距',1.9,1,3)};font-weight:${zoneNumber('正文粗细',400,400,700)};color:${esc(data['正文颜色']||data['文字颜色'])};font-family:${font==='宋体'?'SimSun,serif':font==='楷体'?'KaiTi,serif':'sans-serif'};--dialogue-color:${esc(data['对白颜色']||'#b64c69')};--action-color:${esc(data['动作颜色']||'#777080')}">${body}</div>`;}if(z.id===3)return`<figure class="zone-preview-picture">${images['剧情配图']?`<img src="${esc(images['剧情配图'])}" alt="剧情配图">`:'<div class="zone-picture-placeholder">剧情配图预留位置</div>'}</figure>`;if(z.id===5)return`<details class="reply-fold" ${open}><summary>${esc(z.name)}</summary><div class="reply-actions">${(z.text?z.text.split(/\n/).map(x=>x.trim()).filter(prototypeGlobal.Boolean):['推门走进去','先询问来意']).map(x=>`<button class="option" data-option="${esc(x)}">${esc(x)} ↗</button>`).join('')}</div></details>`;return`<details class="reply-fold" ${open}><summary>${esc(z.name)}</summary><p>${z.id===1?esc(z.text||'场景目标：推进会面。待处理事项：确认来访者身份。'):z.id===4?esc(z.text||'你已抵达旧城，并约好今天与档案管理员见面。'):esc(z.text||'此处展示该分区的示例内容。')}</p></details>`;}
