function addCanvasShape(form,x,y){const names={rect:'矩形',round:'圆角矩形',ellipse:'椭圆',diamond:'菱形',triangle:'三角形'};const s={name:names[form]||'模块',form,x:prototypeGlobal.Math.max(0,prototypeGlobal.Math.min(70,x)),y:prototypeGlobal.Math.max(0,prototypeGlobal.Math.min(70,y)),w:28,h:72,target:'自定义内容',content:''};if(form==='diamond')s.clip='polygon(50% 0%,100% 50%,50% 100%,0% 50%)';if(form==='triangle')s.clip='polygon(50% 0%,100% 100%,0% 100%)';shapes.push(s);selectedShape=shapes.length-1;pen=false;refresh();}
function closeCanvasPath(){if(points.length<3)return;const xs=points.map(p=>p.x),ys=points.map(p=>p.y),x=prototypeGlobal.Math.min(...xs),y=prototypeGlobal.Math.min(...ys),w=prototypeGlobal.Math.max(...xs)-x,h=prototypeGlobal.Math.max(...ys)-y;if(w<3||h<3){toast('请绘制有面积的轮廓。');return;}shapes.push({name:'自定义轮廓',x,y,w,h:h/100*(q('#ps-canvas')?.clientHeight||280),target:'自定义内容',content:'',clip:'polygon('+points.map(p=>((p.x-x)/w*100)+'% '+((p.y-y)/h*100)+'%').join(',')+')'});selectedShape=shapes.length-1;points=[];pen=false;refresh();}
function drawPenPoints(area){area.querySelectorAll('.pen-node,.pen-segment').forEach(n=>n.remove());points.forEach((p,i)=>{if(i){const prev=points[i-1],dx=(p.x-prev.x)*area.clientWidth/100,dy=(p.y-prev.y)*area.clientHeight/100,line=prototypeGlobal.document.createElement('span');line.className='pen-segment';line.style.cssText=`left:${prev.x}%;top:${prev.y}%;width:${prototypeGlobal.Math.hypot(dx,dy)}px;transform:rotate(${prototypeGlobal.Math.atan2(dy,dx)}rad)`;area.append(line);}const dot=prototypeGlobal.document.createElement('span');dot.className='pen-node'+(i===0?' first':'');dot.style.left=p.x+'%';dot.style.top=p.y+'%';area.append(dot);});}
