function studioDialog(html){let el=q('#studio-dialog');if(!el){el=prototypeGlobal.document.createElement('div');el.id='studio-dialog';el.className='studio-modal';app.append(el);}el.innerHTML=`<section role="dialog" aria-modal="true" class="studio-modal-sheet">${html}</section>`;el.hidden=false;}
function rolePictures(role){const current=role.pictures.find(p=>p.id===role.defaultId)||role.pictures[0];return`<div class="role-current"><div class="role-current-image">${current?`<button data-role-zoom="${current.id}"><img src="${current.url}" alt="${esc(role.name)}当前立绘"></button>`:'<span>尚未配置立绘</span>'}</div><div><strong>${role.defaultId?'创作者指定默认':'当前立绘'}</strong><p class="muted">${role.pictures.length} 张立绘</p><button class="solid" data-role-view="generate">AI 生成立绘</button><button data-role-all>查看全部（${role.pictures.length}）</button><p class="muted">可在生成时添加参考图</p></div></div>`;}
function roleGallery(){const role=roles.find(x=>x.id===activeRole);if(!role)return;const list=roleGalleryScope==='作品图片'?role.pictures:(role.publicPictures||[]),slice=list.slice(roleGalleryPage*12,(roleGalleryPage+1)*12);studioDialog(`<header><strong>${esc(role.name)} · 全部立绘（${list.length}）</strong><button data-studio-close>关闭 ×</button></header><div class="othernav">${['作品图片','公共候选'].map(n=>`<button data-role-gallery-scope="${n}" class="${roleGalleryScope===n?'on':''}">${n}</button>`).join('')}</div><div class="role-gallery-grid">${slice.map(p=>`<article class="role-picture"><button data-role-zoom="${p.id}"><img src="${p.url}" alt="${esc(role.name)}立绘"></button><strong>${role.defaultId===p.id?'默认立绘':'候选立绘'}</strong><div class="row"><button data-gallery-action="default" data-picture-id="${p.id}">设为默认</button><button data-gallery-action="cover" data-picture-id="${p.id}">设为封面</button><button data-gallery-action="mobile" data-picture-id="${p.id}">移动端背景</button><button data-gallery-action="pc" data-picture-id="${p.id}">PC背景</button><button data-gallery-action="regen" data-picture-id="${p.id}">重新生成</button><button data-gallery-action="save" data-picture-id="${p.id}">${p.saved?'取消保存':'保存'}</button><button data-gallery-action="publish" data-picture-id="${p.id}">${p.published?'下架公共':'发布公共'}</button><button data-gallery-action="share" data-picture-id="${p.id}">分享</button><button data-gallery-action="delete" data-picture-id="${p.id}">删除</button><button data-gallery-action="favorite" data-picture-id="${p.id}">${p.favorite?'取消收藏':'收藏'}</button></div></article>`).join('')||'<div class="asset-empty">'+(roleGalleryScope==='作品图片'?'暂无角色图片':'尚未连接公共候选数据')+'</div>'}</div><footer><button data-gallery-page="-1" ${roleGalleryPage===0?'disabled':''}>上一页</button><span>${list.length?roleGalleryPage+1:0} / ${prototypeGlobal.Math.ceil(list.length/12)}</span><button data-gallery-page="1" ${(roleGalleryPage+1)*12>=list.length?'disabled':''}>下一页</button></footer>`);}
r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.openCanvasZone)openCanvasModule(+b.dataset.openCanvasZone);if(b.hasAttribute('data-close-canvas-zone'))returnCanvasModule();if(b.dataset.beautySection!==prototypeGlobal.undefined){beautySection=+b.dataset.beautySection;generatorPurpose='';editor();}if(b.hasAttribute('data-studio-close'))q('#studio-dialog').hidden=true;if(b.hasAttribute('data-role-all')){roleGalleryPage=0;roleGalleryScope='作品图片';roleGallery();}if(b.dataset.roleGalleryScope){roleGalleryScope=b.dataset.roleGalleryScope;roleGalleryPage=0;roleGallery();}if(b.dataset.galleryPage){roleGalleryPage+=+b.dataset.galleryPage;roleGallery();}if(b.dataset.galleryAction){const role=roles.find(x=>x.id===activeRole),p=[...role.pictures,...(role.publicPictures||[])].find(p=>p.id===+b.dataset.pictureId);if(!p)return;const a=b.dataset.galleryAction;if(a==='default'){role.defaultId=p.id;toast('已设为角色默认立绘。');}if(a==='cover'){images['作品封面']=p.url;toast('已设为作品封面。');}if(a==='mobile'||a==='pc'){images[a==='pc'?'PC 背景图':'移动设备背景图']=p.url;toast('已设置'+(a==='pc'?'PC':'移动端')+'作品背景。');}if(a==='favorite'){p.favorite=!p.favorite;toast(p.favorite?'已收藏。':'已取消收藏。');}if(a==='save'){p.saved=!p.saved;toast(p.saved?'已保存到个人图片资产（原型）。':'已从个人图片资产移除（原型）。');}if(a==='share'){toast('尚未连接图片详情分享服务，未生成分享链接。');return;}if(a==='delete'){studioDialog(`<header><strong>删除立绘？</strong></header><p>将删除此角色的这张立绘，默认立绘会恢复为自动选择。</p><div class="row"><button data-role-all>取消</button><button data-confirm-role-picture="${p.id}" class="solid">确认删除</button></div>`);return;}if(a==='publish'){toast('尚未连接公共发布服务，未更改公开状态。');return;}if(a==='regen'){q('#studio-dialog').hidden=true;roleView='generate';editor();return;}editor();preview();roleGallery();}if(b.dataset.roleZoom){const role=roles.find(x=>x.id===activeRole),p=[...role.pictures,...(role.publicPictures||[])].find(p=>p.id===+b.dataset.roleZoom);if(p)studioDialog(`<header><strong>${esc(role.name)}</strong><button data-role-all>返回全部</button><button data-studio-close>关闭 ×</button></header><img class="role-large-image" src="${p.url}" alt="${esc(role.name)}立绘">`);}});
r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||page!==5)return;if(b.dataset.generateImage){e.preventDefault();e.stopImmediatePropagation();generatorPurpose=b.dataset.generateImage;imageRatio=generatorPurpose==='PC 背景图'?'16:9':'9:16';editor();}if(b.dataset.pickAsset){e.preventDefault();e.stopImmediatePropagation();const purpose=b.dataset.pickAsset;studioDialog(`<header><strong>选择${esc(purpose)}</strong><button data-studio-close>关闭 ×</button></header><div class="asset-grid">${prototypeGlobal.Object.entries(images).filter(([k])=>k!=='生图参考图').map(([k,v])=>`<button data-beauty-asset="${esc(k)}" data-purpose="${esc(purpose)}"><img src="${v}" alt="${esc(k)}"></button>`).join('')||'<p class="muted">素材库暂无可用图片。</p>'}</div>`);}},true);
r.addEventListener('click',e=>{const b=e.target.closest('[data-beauty-asset]');if(!b)return;images[b.dataset.purpose]=images[b.dataset.beautyAsset];q('#studio-dialog').hidden=true;editor();preview();toast('背景已更新。');});
r.addEventListener('click',e=>{const b=e.target.closest('[data-confirm-role-picture]');if(!b)return;const role=roles.find(x=>x.id===activeRole),id=+b.dataset.confirmRolePicture,index=role?.pictures.findIndex(p=>p.id===id);if(!role||index<0)return;const removed=role.pictures.splice(index,1)[0];if(role.defaultId===id)role.defaultId=null;for(const key of prototypeGlobal.Object.keys(images))if(images[key]===removed.url)delete images[key];editor();preview();roleGallery();toast('立绘已删除。');});
const traceReference={url:'',name:'',opacity:50};let templateCategory='全部',templateQuery='',templateLimit=12;
const replyTemplates=[{name:'空白状态栏',category:'基础',desc:'从空白内容开始'},{name:'主角信息',category:'角色',desc:'角色属性与当前状态'},{name:'任务进度',category:'剧情',desc:'任务目标和完成情况'},{name:'当前情况',category:'剧情',desc:'时间、地点与场景状态'}];
function templateMatches(){return replyTemplates.filter(t=>(templateCategory==='全部'||t.category===templateCategory)&&t.name.includes(templateQuery.trim()));}
function templateResults(){const list=templateMatches();return`<div class="reply-template-grid">${list.slice(0,templateLimit).map(t=>`<button data-add-zone-template="${t.name}"><div class="template-miniature"><span></span><span></span><span></span></div><strong>${t.name}</strong><small>${t.desc}</small></button>`).join('')||'<p class="muted">没有匹配的模板。</p>'}</div>${list.length>templateLimit?'<button data-template-more>加载更多</button>':''}`;}
function renderTraceReference(){const area=q('#ps-canvas');if(!area)return;area.querySelector('.trace-background')?.remove();if(!traceReference.url)return;const img=prototypeGlobal.document.createElement('img');img.className='trace-background';img.src=traceReference.url;img.alt='临摹参考图';img.draggable=false;img.style.opacity=prototypeGlobal.String(1-traceReference.opacity/100);area.prepend(img);}
r.addEventListener('change',e=>{const t=e.target;if(!t.hasAttribute('data-trace-upload')||!t.files[0])return;const file=t.files[0];if(!file.type.startsWith('image/')){toast('请选择图片文件。');return;}const url=prototypeGlobal.URL.createObjectURL(file),probe=new prototypeGlobal.Image();probe.onload=()=>{if(traceReference.url)prototypeGlobal.URL.revokeObjectURL(traceReference.url);traceReference.url=url;traceReference.name=file.name;editor();if(pen)drawPenPoints(q('#ps-canvas'));toast('参考图已放入画布，仅用于临摹。');};probe.onerror=()=>{prototypeGlobal.URL.revokeObjectURL(url);toast('图片无法读取，请重新选择。');};probe.src=url;});
r.addEventListener('input',e=>{const t=e.target;if(t.hasAttribute('data-trace-opacity')){traceReference.opacity=+t.value;const img=q('.trace-background');if(img)img.style.opacity=prototypeGlobal.String(1-traceReference.opacity/100);q('#trace-opacity-value').textContent=t.value+'%';}if(t.hasAttribute('data-template-search')){templateQuery=t.value;templateLimit=12;q('#reply-template-results').innerHTML=templateResults();}});
r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-trace-remove')){prototypeGlobal.URL.revokeObjectURL(traceReference.url);traceReference.url='';traceReference.name='';editor();if(pen)drawPenPoints(q('#ps-canvas'));toast('临摹参考图已移除。');}if(b.dataset.templateCategory){templateCategory=b.dataset.templateCategory;templateLimit=12;openReplyTemplates();}if(b.hasAttribute('data-template-more')){templateLimit+=12;q('#reply-template-results').innerHTML=templateResults();}});
const generationRoles=new prototypeGlobal.Set();let activeCG=null;
function generationRoleUI(){return`<div class="field"><span>参考角色（可多选）</span><div class="generation-roles">${roles.length?roles.map(role=>{const p=role.pictures?.find(p=>p.id===role.defaultId)||role.pictures?.[0];return`<label class="generation-role"><input type="checkbox" data-generation-role="${role.id}" ${generationRoles.has(role.id)?'checked':''}>${p?`<img src="${esc(p.url)}" alt="">`:''}<span>${esc(role.name||'未命名角色')}<small>${p?'参考角色设定与默认立绘':'参考角色设定 · 暂无立绘'}</small></span></label>`;}).join(''):'<p class="muted">暂无角色，请先在「角色立绘」添加角色。</p>'}</div></div>`;}
function cgInput(c,prop,label,type='text',placeholder=''){return`<label class="field"><span>${label}</span><input type="${type}" data-array="cgs" data-id="${c.id}" data-prop="${prop}" value="${esc(c[prop]??'')}" placeholder="${placeholder}" ${type==='number'?'step="any"':''}></label>`;}
function cgSelect(c,prop,label,options,fallback){return`<label class="field"><span>${label}</span><select data-array="cgs" data-id="${c.id}" data-prop="${prop}">${options.map(x=>`<option value="${esc(x)}" ${(c[prop]||fallback)===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;}
function svLegacyCGTriggerUI(){const c=cgs.find(x=>x.id===activeCG)||cgs[0];return`<div class="row"><strong>图片触发</strong><button class="solid" data-new-image-trigger>＋ 新增图片触发</button></div><div class="cg-workspace"><aside class="unified-directory">${cgs.map((x,i)=>`<button data-select-cg="${x.id}" class="${c?.id===x.id?'on':''}">${esc(x.name||'图片触发 '+(i+1))}</button>`).join('')}</aside><section>${c?`<div class="entrybox"><header><label class="ps-toggle-label"><input type="checkbox" class="ps-toggle" data-array="cgs" data-id="${c.id}" data-prop="enabled" ${c.enabled!==false?'checked':''}>启用此图片触发</label><button data-delete="cgs" data-id="${c.id}">删除</button></header>${cgInput(c,'name','名称','text','为此触发命名')}<div class="cg-image-row">${upload('CG '+c.id,'3/4','110px')}<div>${imageActions('CG '+c.id)}<small class="muted">选择命中条件后展示的图片</small></div></div>${cgSelect(c,'triggerType','触发条件',['关键词触发','对话轮数','数值条件'],'关键词触发')}${(c.triggerType||'关键词触发')==='关键词触发'?`${cgInput(c,'key','触发词','text','多个关键词用逗号分隔')}<div class="grid2">${cgSelect(c,'source','触发区域',['AI','用户','系统'],'AI')}${cgSelect(c,'match','关键词关系',['或','与'],'或')}</div><p class="muted">或：任一关键词命中；与：所填关键词全部命中。</p>`:c.triggerType==='对话轮数'?`${cgSelect(c,'roundMode','触发时机',['到第 N 轮','每隔 N 轮'],'到第 N 轮')}${cgInput(c,'round','轮数 N','number','例如：5')}<p class="muted">玩家发送并收到 AI 回复计为一轮；开场白不计入。</p>`:`<div class="grid2"><label class="field"><span>数值所属分区</span><select data-array="cgs" data-id="${c.id}" data-prop="zoneRef"><option value="">选择分区</option>${zones.filter(z=>z.kind==='status').map(z=>`<option value="${z.id}" ${prototypeGlobal.String(c.zoneRef)===prototypeGlobal.String(z.id)?'selected':''}>${esc(z.name)}</option>`).join('')}</select></label>${cgVariableUI(c)}</div><div class="grid2">${cgSelect(c,'operator','满足条件',['低于','低于或等于','等于','高于或等于','高于'],'低于或等于')}${cgInput(c,'threshold','阈值','number','例如：20')}</div><p class="muted">关联分区中的数值字段；从不满足变为满足时触发，持续满足不重复触发。</p>`}${cgSelect(c,'mapping','区域映射',['背景图片','聊天'],'聊天')}${c.mapping==='背景图片'?cgSelect(c,'device','背景适用设备',['跟随当前设备','仅移动端','仅 PC'],'跟随当前设备'):'<p class="muted">图片插入命中本轮的聊天内容。</p>'}<details><summary>测试当前触发条件</summary><div class="cg-test">${(c.triggerType||'关键词触发')==='关键词触发'?'<label class="field"><span>测试区域</span><select id="cg-test-source"><option>AI</option><option>用户</option><option>系统</option></select></label><label class="field"><span>测试文本</span><textarea id="cg-test-text"></textarea></label>':c.triggerType==='对话轮数'?'<label class="field"><span>当前轮数</span><input id="cg-test-round" type="number" min="1" step="1"></label>':'<div class="grid2"><label class="field"><span>上次数值</span><input id="cg-test-previous" type="number"></label><label class="field"><span>当前数值</span><input id="cg-test-value" type="number"></label></div>'}<button data-test-cg="${c.id}">检测条件</button><p id="cg-test-result" aria-live="polite" class="muted"></p></div></details></div>`:'<p class="muted">暂无图片触发配置。</p>'}</section></div>`;}
function svLegacyMatchImageTrigger(c,state){if(c.enabled===false)return false;const type=c.triggerType||'关键词触发';if(type==='关键词触发'){const keys=(c.key||'').split(/[,，\n]/).map(x=>x.trim()).filter(prototypeGlobal.Boolean);return keys.length>0&&(c.source||'AI')===state.source&&(c.match==='与'?keys.every(k=>(state.text||'').includes(k)):keys.some(k=>(state.text||'').includes(k)));}if(type==='对话轮数'){const n=prototypeGlobal.Number(c.round);return prototypeGlobal.Number.isInteger(n)&&n>0&&prototypeGlobal.Number.isInteger(state.round)&&state.round>0&&(c.roundMode==='每隔 N 轮'?state.round%n===0:state.round===n);}if(!c.zoneRef||!c.variable?.trim()||c.threshold===''||c.threshold==null)return false;const threshold=prototypeGlobal.Number(c.threshold),compare=v=>({'低于':v<threshold,'低于或等于':v<=threshold,'等于':v===threshold,'高于或等于':v>=threshold,'高于':v>threshold}[c.operator||'低于或等于']);return prototypeGlobal.Number.isFinite(state.value)&&prototypeGlobal.Number.isFinite(state.previous)&&prototypeGlobal.Number.isFinite(threshold)&&!compare(state.previous)&&compare(state.value);}
r.addEventListener('change',e=>{const t=e.target;if(t.dataset.generationRole){const id=+t.dataset.generationRole;t.checked?generationRoles.add(id):generationRoles.delete(id);}if(t.dataset.array==='cgs'&&['triggerType','mapping'].includes(t.dataset.prop))editor();});
r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-new-image-trigger')||b.dataset.triggerAsset){const id=nextId++;cgs.push({id,name:'',key:'',source:'AI',match:'或',enabled:true,triggerType:'关键词触发',mapping:'聊天'});activeCG=id;if(b.dataset.triggerAsset)images['CG '+id]=images[b.dataset.triggerAsset];assetTab='CG';editor();}if(b.dataset.selectCg){activeCG=+b.dataset.selectCg;editor();}if(b.dataset.testCg){const c=cgs.find(x=>x.id===+b.dataset.testCg),number=s=>q(s)?.value?.trim()?prototypeGlobal.Number(q(s).value):prototypeGlobal.NaN;const hit=matchImageTrigger(c,{source:q('#cg-test-source')?.value,text:q('#cg-test-text')?.value,round:number('#cg-test-round'),previous:number('#cg-test-previous'),value:number('#cg-test-value')});q('#cg-test-result').textContent=hit?'条件命中，将用于'+(c.mapping||'聊天')+'。'+(images['CG '+c.id]?'':'尚未选择图片。'):'未命中：请检查条件、输入值及启用状态。';}});
const statusThemes=[{"id":"t1","name":"时间系统","reason":"时间是全表唯一的公共基准——倒计时、冷却、衰减、日程、周期事件都要读它。它不进数值层，其余所有带时效的机制都无法成立。","fields":[{"id":"t1-f1","name":"当日分钟数","type":"时钟","description":"0–1439 循环，全局唯一时间源","example":"现在是下午快两点。系统不写「下午」，只记今天已经过了 827 分钟。过了午夜，这个数归零，下面的「第几天」加一。","display":"13:20"},{"id":"t1-f2","name":"绝对天数","type":"计数器","description":"开局起第 N 天，只增","example":"开局那天是第 1 天。睡一觉醒来是第 2 天。不能靠睡觉把天数倒回去。","display":"第 12 天"},{"id":"t1-f3","name":"回合数","type":"计数器","description":"技术计数，独立于游戏内时间","example":"一来一回 47→48；不与战斗回合混加","display":"回合 48"},{"id":"t1-f4","name":"行动点余额","type":"有界量表","description":"每日或每时段重置，仅行动定长模式启用","example":"今天只能认真办 3 件事。你去见了林晚，还剩 2 次。再去公司找上司，今晚就见不成第三个人。","display":"行动点 2/3"},{"id":"t1-f5","name":"各倒计时到期点","type":"到期点","description":"存时间点，不存剩余量","example":"截止存 天=12 分钟=1080，不存「还剩 2 天」","display":"报告截止 3/7 18:00"},{"id":"t1-f6","name":"各冷却到期点","type":"到期点","description":"每日限次、周期事件的下次可用时间","example":"下次可再试存 天=8 分钟=0","display":"明日 00:00 后可再试"},{"id":"t1-f7","name":"各 NPC 上次互动时间戳","type":"到期点","description":"好感衰减与主动联系的唯一输入","example":"林晚上次互动 天=5 分钟=1320","display":"距林晚上次见面 2 天"}]},{"id":"t2","name":"气象系统","reason":"天气是低成本的场景发生器（暴雨=避雨共伞、暴雪=困守一室），同时是隐蔽、追踪、生存判定的输入。但它必须状态机化，否则会逐轮闪烁，反而破坏沉浸。","fields":[{"id":"t2-f1","name":"天气","type":"状态机","description":"带转移表，禁止跳跃","example":"阴→小雨 正常；晴→暴雪 不正常","display":"小雨"},{"id":"t2-f2","name":"天气强度","type":"有界量表","description":"同一天气的烈度","example":"都叫下雨，毛毛雨是 2 分，倾盆是 5 分。到 5 分才强制问你还出不出去。","display":"暴雨 或 小雨（2/5）"},{"id":"t2-f3","name":"已持续 / 剩余时长","type":"到期点","description":"缺则天气闪烁","example":"这场雨从今天上午十点下到下午四点。不记下这两头，下一句模型就会突然放晴。","display":"已下 3 小时 · 预计 16:00 停"},{"id":"t2-f4","name":"累积降水量","type":"计数器","description":"涝、水位、洪水输入","example":"本周累计 38，超阈值地窖进水","display":"本周降水偏多"},{"id":"t2-f5","name":"地面状态","type":"状态机","description":"泥泞 / 积水 / 结冰，长于降水本身","example":"天已经转阴不下雨了，路上还是泥。赶路照样慢。","display":"路面泥泞"},{"id":"t2-f6","name":"风力","type":"有界量表","description":"有独立随机，晴天也可大风","example":"晴 + 风力 4/5，远程命中下降","display":"大风 或 风力 4 级"},{"id":"t2-f7","name":"天气征兆 / 预报","type":"标记","description":"已发布不可改，可以报错","example":"早报 今晚有雨，实际转晴，标记仍保留","display":"预报：今晚有雨"},{"id":"t2-f8","name":"天象异变","type":"状态机","description":"与普通天气并行","example":"天气=夜晴，天象=血月","display":"血月"},{"id":"t2-f9","name":"人工光源 / 控温","type":"状态机 + 量表","description":"火堆、油灯等","example":"火堆=燃着，燃料 3/10","display":"火堆燃烧中 · 柴火将尽"}]},{"id":"t3","name":"身体与生存系统","reason":"所有「行动有代价」的实现基础。没有它，玩家可以无限行动。","fields":[{"id":"t3-f1","name":"HP","type":"有界量表","description":"生命","example":"满血 100，现在 62，到 0 倒地或死亡","display":"生命 62/100"},{"id":"t3-f2","name":"体力","type":"有界量表","description":"爆发与负重行动","example":"赶路 −15，现 40/100，太低就不能再行动","display":"体力 40/100"},{"id":"t3-f3","name":"精力","type":"有界量表","description":"持续注意力","example":"连着谈了三场，精神见底。就会容易引发不灵后果反应（说错话/晕倒）","display":"精力 25/100"},{"id":"t3-f4","name":"饥饿","type":"有界量表（衰减）","description":"未进食随天数上升","example":"过了一天没吃，从有点饿变成明显饿。不是心情，是该找食物了。","display":"饥饿：中 或 有点饿"},{"id":"t3-f5","name":"口渴","type":"有界量表（衰减）","description":"未饮水随时间上升","example":"高温外出后 70，能够影响到行动","display":"口渴：高"},{"id":"t3-f6","name":"体温","type":"有界量表","description":"核心体温；体感另推导","example":"36.8；暴雪+夏装则下探","display":"体温 36.8℃"},{"id":"t3-f7","name":"睡眠债","type":"有界量表（衰减）","description":"缺觉累积","example":"熬夜后 45，强制休息窗口打开","display":"缺觉 或 睡眠债 45"},{"id":"t3-f8","name":"卫生","type":"有界量表","description":"体表清洁","example":"多日未洗 低，社交检定受损","display":"卫生：差"},{"id":"t3-f9","name":"感染度","type":"有界量表","description":"伤口与环境","example":"未处理伤口每日 +8，现 24","display":"感染 24"},{"id":"t3-f10","name":"疼痛","type":"有界量表","description":"行动惩罚","example":"40/100 时禁止奔跑","display":"左腿疼痛"},{"id":"t3-f11","name":"负重","type":"有界量表","description":"持有重量 / 上限","example":"18/25，超重耗行动点","display":"负重 18/25"},{"id":"t3-f12","name":"伤势（分部位）","type":"状态机","description":"按部位","example":"左腿=扭伤，此时就禁止追赶选项","display":"左腿扭伤"},{"id":"t3-f13","name":"异常状态","type":"状态机 + 到期点","description":"中毒 / 醉酒 / 麻痹 / 疾病","example":"现在是中等醉。记下「凌晨一点醒酒」，到点自动去掉，不用每句写还醉几分。","display":"醉酒（中）· 约凌晨 1:00 清醒"},{"id":"t3-f14","name":"衣物保暖值","type":"有界量表","description":"生存保暖","example":"夏装保暖 2，冬季体温结算吃亏","display":"着装：单衣，不挡寒"},{"id":"t3-f15","name":"衣物潮湿度","type":"有界量表","description":"生存潮湿","example":"淋过雨，衣服湿了四成。","display":"衣服淋湿"},{"id":"t3-f16","name":"衣物破损度","type":"有界量表","description":"撕破、磨损","example":"围墙翻越后 破损 25，破损往上加。","display":"裤腿刮破"}]},{"id":"t4","name":"心理与属性系统","reason":"角色成长曲线与判定基准。","fields":[{"id":"t4-f1","name":"SAN / 理智","type":"有界量表","description":"崩溃阈值","example":"看见不该看的 45→32，越低越容易胡言乱语/疯掉","display":"理智 32/100"},{"id":"t4-f2","name":"压力","type":"有界量表","description":"长期负荷","example":"70 时任务检定负修正","display":"压力 70"},{"id":"t4-f3","name":"恐惧","type":"有界量表","description":"即时惊吓","example":"被跟踪后 70","display":"恐惧：高"},{"id":"t4-f4","name":"力量 / 智力 / 敏捷 / 体质 / 魅力等","type":"有界量表","description":"判定基础修正","example":"魅力 14，表示说话更好使，不等于她喜欢你。","display":"魅力 14"},{"id":"t4-f5","name":"等级 / 境界","type":"阶梯","description":"成长档","example":"境界=筑基中期。经验满了也不自动升，要过突破事件。","display":"筑基中期"},{"id":"t4-f6","name":"经验值","type":"量表","description":"升阶燃料","example":"380/500，满了只是「可以突破」，不是已经突破。","display":"经验 380/500"},{"id":"t4-f7","name":"技能熟练度","type":"有界量表","description":"单技能成长","example":"潜行 22/100。做成一次，慢慢往上加一点点。","display":"潜行 22"},{"id":"t4-f8","name":"已解锁技能 / 天赋","type":"标记集合","description":"选项门控","example":"{夜视, 唇语}","display":"技能：夜视、唇语"},{"id":"t4-f9","name":"价值观轴","type":"有界量表","description":"道德 / 正邪 / 人性三选一","example":"只启用人性值 68","display":"人性 68"}]},{"id":"t5","name":"关系系统","reason":"这是互动叙事的核心反馈回路。也是最容易被玩家刷爆的系统，必须有日上限。","fields":[{"id":"t5-f1","name":"好感表层","type":"关系量表","description":"有向，A→B","example":"林晚→玩家表层 62","display":"林晚 好感 62"},{"id":"t5-f2","name":"好感真实","type":"关系量表","description":"有向，可与表层不一致","example":"林晚→玩家真实 41","display":"真实好感 41"},{"id":"t5-f3","name":"信任","type":"关系量表","description":"有向","example":"35，未达要求不托付内容","display":"信任 35"},{"id":"t5-f4","name":"依赖","type":"关系量表","description":"有向","example":"20/100，此时你就是无关紧要","display":"依赖 20"},{"id":"t5-f5","name":"敬畏","type":"关系量表","description":"有向","example":"对上司 50，说话时会收着。","display":"敬畏 50"},{"id":"t5-f6","name":"愧疚","type":"关系量表","description":"有向","example":"说谎后 30，愧疚心里越高会引起的蝴蝶效应","display":"愧疚 30"},{"id":"t5-f7","name":"敌意 / 恨意 / 杀意","type":"关系量表","description":"有向","example":"敌意 55，杀意 0。影响做事/说话的倾向性","display":"敌意 55"},{"id":"t5-f8","name":"忠诚度","type":"关系量表","description":"下属 / 组织","example":"80/100，不同忠诚度所代表的做事/说话都有不同","display":"忠诚 80"},{"id":"t5-f9","name":"好感日上限已用量","type":"计数器","description":"防刷","example":"今日对林晚 12/15。超过每日额度上限时不会再增加好感","display":"今日好感已用 12/15"},{"id":"t5-f10","name":"亲密阶段","type":"阶梯","description":"多数难逆","example":"稳定。","display":"阶段：稳定"},{"id":"t5-f11","name":"关系名分","type":"阶梯","description":"与性关系阶段分列","example":"恋人。","display":"恋人"},{"id":"t5-f12","name":"关系旗帜","type":"标记集合","description":"已告白 / 已背叛 / 已知秘密等","example":"{已告白, 已知秘密}","display":"已告白 · 已知秘密"},{"id":"t5-f13","name":"对方眼中的玩家身份","type":"状态机","description":"马甲、谍战","example":"同事 → 识破后改身份。代表着对方对玩家的态度","display":"她眼中：同事"},{"id":"t5-f14","name":"NPC 之间的关系","type":"关系量表","description":"from/to 不限于玩家","example":"林晚→周宁妒意 40，影响npc之间的行为处事。","display":"林晚 → 周宁 妒意 40"}]},{"id":"t6","name":"任务与进度系统","reason":"剧情推进的骨架，也是防止模型三轮推完全部剧情的约束。","fields":[{"id":"t6-f1","name":"任务状态","type":"状态机","description":"未解锁 / 进行 / 完成 / 失败","example":"进行中 → 到点未完成切失败","display":"进行中"},{"id":"t6-f2","name":"任务进度","type":"计数器","description":"步骤或收集","example":"2/3，进度已完成两份，三份是完全达成","display":"证据 2/3"},{"id":"t6-f3","name":"任务截止时间","type":"到期点","description":"存时间点","example":"天=10 分钟=1080","display":"截止 3/7 18:00"},{"id":"t6-f4","name":"主线阶段","type":"阶梯","description":"章节门控","example":"第二章·调查","display":"主线：第二章 · 调查"},{"id":"t6-f5","name":"分支选择记录","type":"标记集合","description":"不可默改","example":"{放走过证人}","display":"已选择：放过证人"},{"id":"t6-f6","name":"结局倾向值","type":"有界量表","description":"多路并行，本周目运行值","example":"线A 30 / 线B 12","display":"倾向 A 30 / B 12"},{"id":"t6-f7","name":"已解锁成就 / 图鉴 / CG","type":"标记集合","description":"收集与重玩","example":"{CG_雨夜走廊}","display":"已解锁：雨夜走廊"}]},{"id":"t7","name":"资源与经济系统","reason":"资源是行动的燃料，也是据点与生存系统的公共输入。","fields":[{"id":"t7-f1","name":"各类货币","type":"计数器","description":"可多币种","example":"现金 2400，代币 15","display":"现金 ¥2400"},{"id":"t7-f2","name":"物品持有量","type":"计数器","description":"背包件数","example":"绷带 \\*3，药品\\*2","display":"绷带 \\*3，药品\\*2"},{"id":"t7-f3","name":"装备耐久","type":"有界量表","description":"损耗","example":"伞 20/100","display":"伞 耐久 20/100"},{"id":"t7-f4","name":"消耗品余量","type":"有界量表","description":"弹药 / 燃料 / 药品 / 水","example":"净水 2/8 日","display":"净水 还够 2 天"},{"id":"t7-f5","name":"物价与波动","type":"有界量表","description":"指数或倍率","example":"粮价 1.3","display":"粮价 ×1.3"},{"id":"t7-f6","name":"负债","type":"计数器","description":"本金","example":"高利贷 5000","display":"欠款 5000"},{"id":"t7-f7","name":"交易冷却","type":"到期点","description":"同一对象下次可议价","example":"天=6 分钟=480","display":"该商人明日 8:00 后再议"}]},{"id":"t8","name":"据点与组织系统","reason":"经营与生存题材的主循环。它的特点是**多数字段的消耗与产出是自动 tick**，不需要模型参与。","fields":[{"id":"t8-f1","name":"设施等级","type":"阶梯","description":"建筑档","example":"围墙等级 2","display":"围墙 Lv.2"},{"id":"t8-f2","name":"设施损坏度","type":"有界量表","description":"完好程度","example":"损坏 35/100","display":"围墙损坏 35%"},{"id":"t8-f3","name":"人口","type":"计数器","description":"总人数","example":"18人","display":"人口 18"},{"id":"t8-f4","name":"闲置人力","type":"计数器","description":"可派工","example":"3人","display":"闲置 3 人"},{"id":"t8-f5","name":"士气","type":"有界量表","description":"低位出事件","example":"38/100 触发抱怨","display":"士气 低 或 士气 28"},{"id":"t8-f6","name":"凝聚力","type":"有界量表","description":"内部分裂","example":"40/100  各派系开始各说各的。","display":"凝聚力 40"},{"id":"t8-f7","name":"防御值","type":"有界量表","description":"遇袭结算","example":"55  遇袭时和敌人强度对算。","display":"防御 55"},{"id":"t8-f8","name":"隐蔽度","type":"有界量表","description":"被发现权重","example":"60   不是绝对安全","display":"隐蔽 60"},{"id":"t8-f9","name":"威胁等级","type":"有界量表","description":"外部压力","example":"4级   巡逻和袭击更勤。","display":"外部威胁 4"},{"id":"t8-f10","name":"仓库存量","type":"计数器","description":"分项","example":"粮食 120","display":"粮食 120"},{"id":"t8-f11","name":"建造 / 生产完成时间","type":"到期点","description":"队列结束时刻","example":"天=9 分钟=0","display":"工坊升级 3/9 完成"},{"id":"t8-f12","name":"对外关系值","type":"关系量表","description":"对象 + 类型取值","example":"邻营=贸易 40  和邻营是贸易，热络程度 40。结盟、敌对是关系类型，不是并排三个独立条。","display":"邻营：贸易 40"},{"id":"t8-f13","name":"叛逃风险","type":"有界量表","description":"离队权重","example":"15 偏低，但仍要盯夜班。","display":"叛逃风险 低"},{"id":"t8-f14","name":"内奸嫌疑","type":"有界量表","description":"夜谈权重","example":"22 夜谈、对质的戏份会更容易抽中。","display":"内奸嫌疑 22"}]},{"id":"t9","name":"战斗系统","reason":"唯一需要逐回合精确结算的系统，也是最不能交给模型算的。","fields":[{"id":"t9-f1","name":"我方 / 敌方 HP","type":"有界量表","description":"本场生命","example":"敌 18/40   对方 40 滴血还剩 18。","display":"敌 18/40 我 72/100"},{"id":"t9-f2","name":"护盾","type":"有界量表","description":"先于 HP 扣除","example":"6    还有 6 点盾，盾没破之前少扣血。","display":"护盾 6/20"},{"id":"t9-f3","name":"架势","type":"有界量表","description":"破防输入","example":"破防中    架势已经被打崩，下一击更好打中。","display":"架势已破"},{"id":"t9-f4","name":"内力 / 魔力 / 灵力","type":"有界量表","description":"本场资源","example":"10/50   够不够放技能","display":"灵力 10/50"},{"id":"t9-f5","name":"增益 / 减益结束点","type":"到期点","description":"用战斗回合计","example":"流血在战斗第 6 回合结束。用战斗回合计，不拿世界钟来减。","display":"流血 · 剩 2 回合"},{"id":"t9-f6","name":"技能冷却","type":"到期点","description":"用战斗回合计","example":"重击可用=战斗回合 8    重击要到战斗第 8 回合才能再砸。","display":"重击冷却中（第 8 回合可用）"},{"id":"t9-f7","name":"战斗回合数","type":"计数器","description":"与全局回合分离","example":"5    现在第 5 回合。和聊天回合是两本账。","display":"战斗第 5 回合"},{"id":"t9-f8","name":"战斗阶段","type":"状态机","description":"遭遇 / 交锋 / 溃逃等","example":"交锋","display":"交锋"},{"id":"t9-f9","name":"增援倒计时","type":"到期点","description":"用战斗回合计","example":"敌增援=战斗回合 7      敌人救兵战斗第 7 回合到。","display":"敌增援 2 回合后到达"}]},{"id":"t10","name":"系统元层","reason":"跨周目与存档相关，以及运行时的模块管理。","fields":[{"id":"t10-f1","name":"周目数","type":"计数器","description":"第几周目","example":"第 2 周目。","display":"第 2 周目"},{"id":"t10-f2","name":"读档次数","type":"计数器","description":"本周目或累计","example":"6    已经读了 6 次。","display":"读档 6"},{"id":"t10-f3","name":"Bad End 计数","type":"计数器","description":"已触发坏结局次数","example":"1    坏结局走过 1 次。","display":"坏结局 ×1"},{"id":"t10-f4","name":"已解锁结局 / CG","type":"标记集合","description":"跨周目累计","example":"{结局_离开城市}  「离开城市」这条结局已经见过。","display":"已见结局：离开城市"},{"id":"t10-f5","name":"跨周目继承标记","type":"标记集合","description":"继承记忆或道具权","example":"{记得仓库暗格} 还记得仓库有暗格。","display":"继承：记得暗格"},{"id":"t10-f6","name":"当前挂载模块","type":"标记集合","description":"运行时子系统","example":"{职场, 情欲}","display":"模块：职场 / 情欲"},{"id":"t10-f7","name":"章节 / 幕","type":"阶梯","description":"叙事单元","example":"第3章第2幕","display":"第三章 · 第二幕"}]},{"id":"t11","name":"情欲系统","reason":"互动叙事里，情欲是第二条反馈回路，和第五类关系平行：关系管「愿不愿意靠近」，情欲管「身体此刻处在哪一阶段、下场还能否继续、会留下什么后果」。不单独建层，就会和第三类生存、第五类好感抢同一组数，出现「好感 80 却无法表达未发生关系」或「高潮后立刻再战」的穿帮。它必须可读时间系统的到期点（不应期、余韵、安全期、孕周），必须可关（模块开关在第十类），且不得用于未成年角色。","fields":[{"id":"t11-f1","name":"玩家性欲","type":"有界量表","description":"读时间衰减","example":"58    当前58，无刺激时间一长会自己往下掉。","display":"性欲 58"},{"id":"t11-f2","name":"玩家兴奋 / 快感累积","type":"有界量表","description":"高潮后清零或打折","example":"累积 70/100    100 满，现在 70。到顶按规则高潮，然后这一格清掉或打折。","display":"快感 70/100"},{"id":"t11-f3","name":"距高潮余量","type":"有界量表","description":"可与阈值−累积互推","example":"余量 8    还差 8。模型不能跳过这一格直接写她高潮了。","display":"接近高潮"},{"id":"t11-f4","name":"是否边缘","type":"标记","description":"防模型直接写高潮","example":"是     下一回有效刺激才允许结算高潮。","display":"边缘"},{"id":"t11-f5","name":"勃起程度","type":"阶梯","description":"不必连续百分","example":"半勃起状态","display":"半勃"},{"id":"t11-f6","name":"精液储量","type":"有界量表","description":"回复读时间钟","example":"2/3   满格 3，还剩 2。过一段时间按世界钟往回补。","display":"余量 2/3"},{"id":"t11-f7","name":"本场已射次数","type":"计数器","description":"场结束可清","example":"1    这场结束可以清掉。","display":"本场 1 次"},{"id":"t11-f8","name":"不应/硬期到期点","type":"到期点","description":"存可再战时刻","example":"天=4 分钟=900","display":"不硬期/虚弱期至 15:00"},{"id":"t11-f9","name":"余韵到期点","type":"到期点","description":"结束前限制外出再战","example":"天=4 分钟=820","display":"余韵中"},{"id":"t11-f10","name":"人物欲情","type":"有界量表","description":"按人","example":"林晚 45","display":"林晚 欲情 45"},{"id":"t11-f11","name":"人物湿润 / 润滑","type":"有界量表","description":"按人，按分钟衰减","example":"湿润 40","display":"湿润：中"},{"id":"t11-f12","name":"人物本场高潮次数","type":"计数器","description":"离场可卸载","example":"2    离开这场情欲就可以清或封存。","display":"已高潮 2 次"},{"id":"t11-f13","name":"解衣进度","type":"阶梯","description":"完好→解扣→褪层→近无","example":"上衣解开、裙在","display":"袒胸露乳，下本身完好"},{"id":"t11-f14","name":"情欲浸湿","type":"有界量表","description":"与生存潮湿分账","example":"30","display":"腿间浸湿"},{"id":"t11-f15","name":"性关系阶段","type":"阶梯","description":"禁止跳级","example":"已抚慰，本轮不得写插入","display":"已抚慰"},{"id":"t11-f16","name":"初夜已完成","type":"标记","description":"一人一记","example":"林晚=否   一人一记。","display":"初夜：未"},{"id":"t11-f17","name":"已解锁行为","type":"标记集合","description":"未经历则隐藏","example":"{亲吻, 抚慰}","display":"已解锁：吻、抚慰"},{"id":"t11-f18","name":"禁止行为","type":"标记集合","description":"硬门控","example":"{公开}","display":"禁止：公开"},{"id":"t11-f19","name":"内射允许策略","type":"阶梯","description":"禁止 / 偶尔 / 默认","example":"禁止    没改之前，结算不能写成内射","display":"内射：禁止"},{"id":"t11-f20","name":"内射累计","type":"计数器","description":"孕检输入","example":"0 次     影响到怀孕","display":"内射累计 0"},{"id":"t11-f21","name":"满足度","type":"关系量表","description":"相对玩家","example":"20    是否已经满足","display":"满足 20"},{"id":"t11-f22","name":"上瘾度 / 索求倾向","type":"关系量表","description":"读情欲时间戳","example":"索求 15","display":"索求 低"},{"id":"t11-f23","name":"避孕是否执行（本场）","type":"标记","description":"当场一记","example":"未执行","display":"本场未避孕"},{"id":"t11-f24","name":"生理周期相位","type":"阶梯","description":"由月经锚点+绝对天数推","example":"锚点 天=2，今日=卵前期","display":"卵前期"},{"id":"t11-f25","name":"危险期标记","type":"标记","description":"由相位推导可只存标记","example":"是","display":"危险期"},{"id":"t11-f26","name":"有孕状态","type":"状态机","description":"与知情分离","example":"未孕","display":"未孕"},{"id":"t11-f27","name":"受孕日","type":"时间戳","description":"孕周由此+绝对天数推导","example":"若发生则存 天=11","display":"（后台）或 孕周第 6 周"},{"id":"t11-f28","name":"怀孕知情","type":"标记","description":"可晚于有孕","example":"有孕=是，知情=否","display":"她尚不知情"},{"id":"t11-f29","name":"上次情欲互动时间戳","type":"时间戳","description":"与社交上次互动分开","example":"天=6 分钟=1410","display":"距上次 2 天"},{"id":"t11-f30","name":"痕迹待处理","type":"标记集合 + 到期点","description":"吻痕 / 精斑 / 气味","example":"{颈侧吻痕} 到期 天=7 分钟=480","display":"颈侧吻痕 · 明日午前仍可见"}]}];
let statusThemeId='t1',statusEditId=null;const statusSelections=new prototypeGlobal.Map();
function currentStatusTheme(){return statusThemes.find(x=>x.id===statusThemeId)||statusThemes[0];}
function selectedStatusFields(){if(!statusSelections.has(statusThemeId))statusSelections.set(statusThemeId,new prototypeGlobal.Set());return statusSelections.get(statusThemeId);}
function statusThemeDetail(){const t=currentStatusTheme(),picked=selectedStatusFields();return`<header class="status-theme-title"><div><h3>${esc(t.name)}</h3><p>${esc(t.reason.split('。')[0])}。</p></div><span>${t.fields.length} 项内容</span></header><div class="status-field-heading"><strong>选择需要的内容</strong><div><button data-status-select-all>全选</button><button data-status-clear>清空</button></div></div><div class="status-field-list">${t.fields.map(f=>`<label class="status-field-choice"><input type="checkbox" data-status-pick="${f.id}" ${picked.has(f.id)?'checked':''}><span><strong>${esc(f.name)}</strong><small>${esc(f.description)}</small></span><span class="status-field-example"><small>显示示例</small>${esc(f.display)}</span></label>`).join('')}</div><div class="status-selection-preview"><strong>将添加的内容</strong><p id="status-picked-text">${t.fields.filter(f=>picked.has(f.id)).map(f=>esc(f.name)).join(' · ')||'尚未选择，勾选上方需要的项目。'}</p></div><p class="muted">示例用于说明显示方式，不会作为开局数值。${['t1','t2','t3','t5','t6','t7','t8','t11'].includes(t.id)?'涉及持续时间、到期、冷却或衰减的字段，需要关联统一时间基准。':''}${t.id==='t9'?'战斗回合与聊天回合分开计数。':''}${t.id==='t11'?'仅适用于成年角色。':''}</p><footer class="status-theme-footer"><span id="status-picked-count">已选 ${picked.size} / ${t.fields.length} 项</span><button class="solid" data-status-confirm ${picked.size?'':'disabled'}>${statusEditId?'保存内容选择':'添加所选内容'}</button></footer>`;}
function openReplyTemplates(){statusEditId=null;statusSelections.clear();statusThemeId='t1';openStatusThemeDialog();}
function openStatusThemeDialog(){studioDialog(`<header><strong>${statusEditId?'调整分区内容':'添加新的分区'}</strong><button data-studio-close>关闭 ×</button></header><div class="status-theme-workspace"><aside class="status-theme-directory"><div class="zone-list-head">状态栏主题</div>${statusThemes.map(t=>`<button data-status-theme="${t.id}" class="${t.id===statusThemeId?'on':''}" ${statusEditId&&t.id!==statusThemeId?'disabled':''}><span>${esc(t.name)}</span><small>${t.fields.length} 项</small></button>`).join('')}${statusEditId?'':'<button data-status-blank>＋ 空白自定义分区</button>'}</aside><section id="status-theme-detail">${statusThemeDetail()}</section></div>`);}
function updateStatusSelection(){const t=currentStatusTheme(),picked=selectedStatusFields();q('#status-picked-count').textContent=`已选 ${picked.size} / ${t.fields.length} 项`;q('#status-picked-text').textContent=t.fields.filter(f=>picked.has(f.id)).map(f=>f.name).join(' · ')||'尚未选择，勾选上方需要的项目。';q('[data-status-confirm]').disabled=!picked.size;}
function svLegacyCGVariableUI(c){const z=zones.find(z=>prototypeGlobal.String(z.id)===prototypeGlobal.String(c.zoneRef));if(!z?.fields)return cgInput(c,'variable','数值字段','text','例如：主角.精力');const list=z.fields.filter(f=>/量表|计数器|量表（|量表\s/.test(f.type));return`<label class="field"><span>关联数值</span><select data-array="cgs" data-id="${c.id}" data-prop="variable"><option value="">选择已添加的数值</option>${list.map(f=>`<option value="${f.id}" ${c.variable===f.id?'selected':''}>${esc(statusFieldName(z,f))}</option>`).join('')}</select>${list.length?'':'<small>该分区没有可比较的数值项。</small>'}</label>`;}
r.addEventListener('change',e=>{const t=e.target;if(t.dataset.statusPick){const picked=selectedStatusFields();t.checked?picked.add(t.dataset.statusPick):picked.delete(t.dataset.statusPick);updateStatusSelection();}if(t.dataset.statusVisible){const f=activeZone()?.fields?.find(f=>f.id===t.dataset.statusVisible);if(f){f.visible=t.checked;preview();}}if(t.dataset.array==='cgs'&&t.dataset.prop==='zoneRef'){const c=cgs.find(c=>c.id===+t.dataset.id);if(c)c.variable='';editor();}});
r.addEventListener('input',e=>{const t=e.target;if(t.dataset.statusValue){const f=activeZone()?.fields?.find(f=>f.id===t.dataset.statusValue);if(f){f.value=t.value;preview();}}});
r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.statusTheme){statusThemeId=b.dataset.statusTheme;openStatusThemeDialog();}if(b.hasAttribute('data-status-select-all')||b.hasAttribute('data-status-clear')){statusSelections.set(statusThemeId,new prototypeGlobal.Set(b.hasAttribute('data-status-select-all')?currentStatusTheme().fields.map(f=>f.id):[]));q('#status-theme-detail').innerHTML=statusThemeDetail();}if(b.dataset.statusEdit){const z=zones.find(z=>z.id===+b.dataset.statusEdit);statusEditId=z.id;statusThemeId=z.themeId;statusSelections.set(statusThemeId,new prototypeGlobal.Set(z.fields.map(f=>f.definitionId||f.id)));openStatusThemeDialog();}if(b.hasAttribute('data-status-confirm')){const t=currentStatusTheme(),picked=selectedStatusFields();if(!picked.size)return;let z=zones.find(z=>z.id===statusEditId);if(!z){z={id:nextId++,name:t.name,kind:'status',enabled:false,fold:'收起',text:'',themeId:t.id,themeName:t.name};zones.push(z);}const old=z.fields||[];z.fields=t.fields.filter(f=>picked.has(f.id)).flatMap(f=>{const kept=old.filter(o=>(o.definitionId||o.id)===f.id);return kept.length?kept:[{...f,value:'',visible:true}];});zoneId=z.id;sceneSelected=prototypeGlobal.String(z.id);if(sv.ready)sv.selectedUI=prototypeGlobal.String(z.id);q('#studio-dialog').hidden=true;refresh();toast(statusEditId?'已更新分区包含内容。':'已添加'+t.name+'，可开启并在画布调整外观。');}if(b.hasAttribute('data-status-blank')){const z={id:nextId++,name:'自定义状态栏',kind:'status',enabled:false,fold:'收起',text:''};zones.push(z);zoneId=z.id;sceneSelected=prototypeGlobal.String(z.id);if(sv.ready)sv.selectedUI=prototypeGlobal.String(z.id);q('#studio-dialog').hidden=true;refresh();}});
let creatorCanvasOpenMode='inline',canvasSecondaryZone=null,canvasReturnScroll=0,canvasReturnOuterScroll=0;
function rememberCanvasScroll(){canvasReturnScroll=q('#ps-screen').scrollTop;canvasReturnOuterScroll=q('.previewcontent').scrollTop;}
function restoreCanvasScroll(){q('#ps-screen').scrollTop=canvasReturnScroll;q('.previewcontent').scrollTop=canvasReturnOuterScroll;}
function openCanvasModule(id){rememberCanvasScroll();if(creatorCanvasOpenMode==='page'){expandedCanvasZone=null;canvasSecondaryZone=id;preview();q('#ps-screen').scrollTop=0;q('.previewcontent').scrollTop=0;q('[data-canvas-back]')?.focus({preventScroll:true});}else{canvasSecondaryZone=null;expandedCanvasZone=id;preview();restoreCanvasScroll();q('[data-close-canvas-zone]')?.focus({preventScroll:true});}}
function returnCanvasModule(){const id=canvasSecondaryZone??expandedCanvasZone;canvasSecondaryZone=null;expandedCanvasZone=null;preview();restoreCanvasScroll();q(`[data-open-canvas-zone="${id}"]`)?.focus({preventScroll:true});}
r.addEventListener('change',e=>{if(e.target.hasAttribute('data-creator-canvas-open')){creatorCanvasOpenMode=e.target.value;canvasSecondaryZone=null;expandedCanvasZone=null;toast(creatorCanvasOpenMode==='page'?'已设置：打开二级页面。':'已设置：在画布下方展开。');preview();}});
r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-canvas-back')){returnCanvasModule();return;}if(b.dataset.option&&canvasSecondaryZone!==null){e.preventDefault();e.stopImmediatePropagation();const option=b.dataset.option;returnCanvasModule();const self=q('#ps-self');if(self)self.textContent=option;fit();}},true);
let shapeAppearanceTab='closed';const bubbleAppearance={};
function appearanceTarget(scope){if(scope==='bubble')return bubbleAppearance;const s=shapes[selectedShape];if(!s)return null;if(scope==='closed')return s.closedAppearance||(s.closedAppearance={});const z=zones.find(z=>z.id===s.zoneId);return z?(z.openAppearance||(z.openAppearance={})):null;}
