function stCurve(points,pen,closed){if(points.length<2)return points;const out=[],n=points.length,segments=closed?n:n-1;for(let i=0;i<segments;i++){const p=points[i],q=points[(i+1)%n],prev=points[(i-1+n)%n],next=points[(i+2)%n];const c1=pen?{x:p.x+(p.dx||0),y:p.y+(p.dy||0)}:{x:p.x+(q.x-prev.x)/6,y:p.y+(q.y-prev.y)/6},c2=pen?{x:q.x-(q.dx||0),y:q.y-(q.dy||0)}:{x:q.x-(next.x-p.x)/6,y:q.y-(next.y-p.y)/6};for(let k=0;k<=12;k++){const t=k/12,u=1-t;out.push({x:u*u*u*p.x+3*u*u*t*c1.x+3*u*t*t*c2.x+t*t*t*q.x,y:u*u*u*p.y+3*u*u*t*c1.y+3*u*t*t*c2.y+t*t*t*q.y});}}return out;}
