r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-flow-templates')){flowTemplates=!flowTemplates;editor();}if(b.hasAttribute('data-flow-pen')){if([2,3].includes(prototypeGlobal.Number(sceneSelected.replace('open-','')))){toast('请先选择一个状态栏入口，再绘制它的轮廓。');return;}flowPen=!flowPen;flowPoints=[];editor();}if(b.dataset.flowForm)flowApplyForm(b.dataset.flowForm);if(b.hasAttribute('data-flow-clear-reference')){flowReference='';editor();}if(b.dataset.flowDemo)flowOffer(b.dataset.flowDemo);if(b.hasAttribute('data-flow-accept')){sceneRemember();if(flowProposal==='paper')sceneDesign.theme='paper';else if(flowProposal==='prepare'){if(!zones.some(z=>z.name==='调查进度'))zones.push({id:nextId++,name:'调查进度',enabled:true,kind:'status',fold:'收起',text:'当前任务：查明灯塔亮起原因\n已获得线索：来信邮戳、灯塔灯光',source:'世界书 · 示例预设'});}flowProposal=null;q('#ps-agent-result').textContent='演示修改已应用，可在画布中继续调整。';editor();sceneRefresh();}if(b.hasAttribute('data-flow-cancel')){flowProposal=null;q('#ps-agent-result').textContent='已取消，作品保持原样。';}if(b.dataset.act==='agent-send'){e.stopImmediatePropagation();studioOffer();}},true);
