function svLegacyApplyManagedCSS(text){const rules=[...text.matchAll(/([^{}]+)\{([^{}]*)\}/g)],rest=[];sceneRemember();for(const[,selector,body]of rules){const sel=selector.trim();if(!['.reply-body','.reply-bubble'].includes(sel)){rest.push(selector+'{'+body+'}');continue;}const unknown=[];for(const item of body.split(';')){if(!item.trim())continue;const split=item.indexOf(':'),key=item.slice(0,split).trim(),v=item.slice(split+1).trim(),n=prototypeGlobal.parseFloat(v);let applied=false;if(sel==='.reply-body'){const map={'font-size':'正文字号','line-height':'正文行间距','letter-spacing':'正文字间距'};if(map[key]&&prototypeGlobal.Number.isFinite(n)){data[map[key]]=key==='font-size'?stClamp(n,12,48):key==='line-height'?stClamp(n,1,3):stClamp(n,-1,10);applied=true;}if(key==='color'&&/^#[0-9a-f]{6}$/i.test(v)){data['正文颜色']=v;applied=true;}}else{const a=sceneSettings('2');if(key==='background-color'&&/^#[0-9a-f]{6}$/i.test(v)){a.tint=v;applied=true;}if(key==='border-radius'&&prototypeGlobal.Number.isFinite(n)){a.radius=stClamp(n,0,100);applied=true;}if(key==='opacity'&&prototypeGlobal.Number.isFinite(n)){a.opacity=stClamp(n*100,0,100);applied=true;}}if(!applied)unknown.push(item);}if(unknown.length)rest.push(sel+' { '+unknown.join(';')+'; }');}studioCSSExtra=rest.join('\n');data['整体内置 CSS']=text;editor();preview();toast('支持的属性已同步；'+(rest.length?'其他 CSS 保留为未执行扩展。':'画布与正文样式已更新。'));}
function linkagePass(){return stRulePass({...studioLink,enabled:studioLink.enabled});}
