function svLegacyLinkedCharacterPreview(){const role=linkedRole();if(!role||!studioLink.speaking)return'';const url=linkedImage();return`<div class="linked-runtime" style="--linked-color:${linkagePass()?studioLink.color:'var(--scene-accent)'}"><div class="linked-role-summary">${url?`<img src="${esc(url)}" alt="${esc(role.name)}的当前立绘">`:''}<div><strong>${esc(role.name)}</strong><small>${url?'已关联角色立绘':'未添加立绘 · 保留文字表现'}</small></div>${stCanvasRender?'':`<button data-linked-speak aria-label="朗读角色对白">朗读</button>`}</div><p>“邮戳是昨天的，可这座灯塔，已经废弃十年了。”</p>${studioLink.thinking?'<small>心理：这束灯光，也许与来信有关。</small>':''}<div class="linked-runtime-note">${studioLink.enabled?(linkagePass()?'条件命中 · 使用条件表现':'条件未命中 · 使用默认表现'):'角色对白与心理共用角色绑定'}</div></div>`;}
function linkAssetOptions(selected){return'<option value="">未指定 · 保留默认</option>'+libraryEntries().map(([key])=>`<option value="${esc(key)}" ${key===selected?'selected':''}>${esc(key)}</option>`).join('');}
function linkageUI(){const role=linkedRole();return`<div class="link-workspace"><aside class="link-directory"><strong>角色与联动</strong>${roles.map(x=>`<button data-link-role="${x.id}" class="${prototypeGlobal.Number(studioLink.roleId)===x.id?'on':''}">${esc(x.name)}</button>`).join('')}<button data-open-role-library>管理角色 / 立绘</button></aside><section><div class="entrybox"><header><strong>${esc(role?.name||'选择角色')} · 角色绑定</strong></header><p class="muted">对白、心理与立绘共用一个角色归属。没有图片时不会自动匹配不存在的素材。</p><div class="row"><label class="check"><input type="checkbox" data-link="speaking" ${studioLink.speaking?'checked':''}>专属对白</label><label class="check"><input type="checkbox" data-link="thinking" ${studioLink.thinking?'checked':''}>同步心理</label></div><label class="field"><span>默认立绘</span><select data-link="normalImage">${linkAssetOptions(studioLink.normalImage)}</select></label><label class="field"><span>上传此角色的默认立绘</span><input type="file" accept="image/*" data-link-upload="normalImage"></label><div class="grid2"><label class="field"><span>音色（浏览器演示）</span><select data-link="voice"><option value="">系统中文音色</option>${(prototypeGlobal.window.speechSynthesis?.getVoices()||[]).filter(v=>v.lang.startsWith('zh')).map(v=>`<option ${studioLink.voice===v.name?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><label class="field"><span>默认语速</span><input type="number" min="0.5" max="2" step="0.1" data-link="rate" value="${studioLink.rate}"></label></div></div><div class="entrybox"><header><strong>状态变化 → 同步改变表现</strong><label class="check"><input type="checkbox" data-link="enabled" ${studioLink.enabled?'checked':''}>启用</label></header><div class="grid2"><label class="field"><span>当状态</span><select data-link="variable">${stVariables().map(v=>`<option value="${v.id}" ${studioLink.variable===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><label class="field"><span>达到或超过</span><input type="number" data-link="threshold" value="${studioLink.threshold}"></label></div><div class="link-effects">${[['portrait','角色图片'],['bubble','气泡流光'],['bgm','背景音乐'],['tts','说话语速']].map(([key,label])=>`<label class="check"><input type="checkbox" data-link-effect="${key}" ${studioLink.effects[key]?'checked':''}>${label}</label>`).join('')}</div><label class="field"><span>命中后的角色图片</span><select data-link="activeImage">${linkAssetOptions(studioLink.activeImage)}</select></label><label class="field"><span>上传条件图片</span><input type="file" accept="image/*" data-link-upload="activeImage"></label><div class="grid2"><label class="field"><span>流光颜色</span><input type="color" data-link="color" value="${studioLink.color}"></label><label class="field"><span>命中后的语速</span><input type="number" min="0.5" max="2" step="0.1" data-link="activeRate" value="${studioLink.activeRate}"></label></div><div class="grid2"><label class="field"><span>常规 BGM</span><input type="file" accept="audio/*" data-link-audio="normalMusic"><small>${studioLink.normalMusic?'已添加音频':'未添加，不会播放'}</small></label><label class="field"><span>条件 BGM</span><input type="file" accept="audio/*" data-link-audio="activeMusic"><small>${studioLink.activeMusic?'已添加音频':'未添加，不会播放'}</small></label></div><p class="muted">条件结束恢复默认表现。条件 BGM 暂停常规 BGM，结束后从暂停处继续；未上传素材则保持原状。</p><div class="row"><button data-link-test="hit">模拟达到条件</button><button data-link-test="reset">恢复初始状态</button><button data-link-audio-start>允许播放音频</button><button data-link-audio-stop>停止音频</button></div></div></section></div>`;}
function runLinkAudio(){const hit=linkagePass();if(!studioRuntime.playing||!studioLink.effects.bgm)return;if(hit&&studioLink.activeMusic){if(!studioRuntime.lastHit)triggerTrack({id:'studio-link',name:'状态联动音轨',url:studioLink.activeMusic,loop:false,volume:.5});}else if(studioRuntime.lastHit)endTrigger();studioRuntime.lastHit=hit;}
function quickRole(){return roles[0]||null;}
function quickField(key,label,multi=false){return`<label class="field"><span>${label}</span>${multi?`<textarea data-field="${key}">${esc(data[key]||'')}</textarea>`:`<input data-field="${key}" value="${esc(data[key]||'')}">`}</label>`;}
function quickEditorUI(){const role=quickRole();let html='';if(studioStep===0)html=`<div class="profile-heading">${upload('作品封面','3/4','150px')}<div class="profile-copy">${quickField('作品名称','作品名称')}${quickField('简介','作品简介',true)}</div></div><div class="row"><button data-quick-gen="cover">✦ AI 生成封面</button><span class="muted">封面 3:4 · 可先留空</span></div>${wholeThemeUI()}`;if(studioStep===1)html=`<section class="entrybox"><header><strong>角色设定</strong></header>${[['name','角色名称'],['identity','身份'],['goal','目标'],['secret','秘密'],['description','性格']].map(([key,label])=>`<label class="field"><span>${label}</span><${key==='description'?'textarea':'input'} data-quick-role="${key}" ${key==='description'?'':`value="${esc(role?.[key]||'')}"`}>${key==='description'?esc(role?.[key]||'')+'</textarea>':''}</label>`).join('')}<label class="field"><span>角色立绘（可选）</span><input type="file" accept="image/*" data-quick-portrait></label>${role?.pictures?.length?`<img class="quick-portrait" src="${esc(role.pictures[0].url)}" alt="当前角色立绘">`:'<p class="muted">暂无立绘，不自动关联图片。填写角色也能先完成文字作品。</p>'}<button data-quick-gen="portrait">✦ AI 生成立绘</button></section>`;if(studioStep===2)html=`${quickField('系统提示词','世界与剧情',true)}${quickField('前置词','希望 AI 遵守的规则',true)}<label class="field"><span>开场内容</span><textarea data-zone-quick="2">${esc(zones.find(z=>z.id===2)?.text||'')}</textarea></label><p class="muted">右侧直接查看作品效果。复杂数值和条件演出留到高级创作。</p>`;if(studioStep===3)html=`<section class="entrybox"><header><strong>${esc(data['作品名称']||'未命名作品')}</strong></header><p>${esc(data['简介']||'尚未填写简介')}</p><div class="quick-review"><div>美化模板<span>${sceneThemes[sceneDesign.theme].name}</span></div><div>角色设定<span>${esc(role?.name||'未填写')}</span></div><div>角色立绘<span>${role?.pictures?.length?'已上传':'未添加 · 文字作品可继续'}</span></div><div>页面适配<span>PC / 手机自动适配</span></div></div><p class="muted">当前为本地原型，尚未接入 AI 生成与线上发布。</p><button data-quick-save>保存本地作品配置</button></section>`;return`<div class="quick-step-heading"><small>快速创作 · ${studioStep+1} / 4</small><h3>${studioQuickSteps[studioStep]}</h3></div>${html}<div class="quick-step-footer"><button data-quick-prev ${studioStep===0?'disabled':''}>上一步</button><button class="solid" data-quick-next>${studioStep<3?'继续：'+studioQuickSteps[studioStep+1]:'进入高级创作'}</button></div>`;}
function renderQuickEditor(){q('#ps-editor').innerHTML=`<div class="edithead"><h3>把你的想法变成作品</h3></div><div class="body">${quickEditorUI()}</div>`;q('#ps-editor').append(psAssistant);q('#ps-context').textContent='正在协助：'+studioQuickSteps[studioStep];q('#ps-nav').innerHTML='<div class="navcaption">快速创作</div>'+studioQuickSteps.map((name,i)=>`<button class="navbutton ${studioStep===i?'on':''}" data-quick-step="${i}"><b class="navnum">${i+1}</b><span>${name}</span></button>`).join('');q('#ps-mobile-nav').innerHTML=studioQuickSteps.map((name,i)=>`<option value="${i}" ${studioStep===i?'selected':''}>${name}</option>`).join('');q('#st-test-controls')?.setAttribute('hidden','');}
function installStudioChrome(){const btn=prototypeGlobal.document.createElement('button');btn.dataset.studioMode='';btn.textContent='高级创作 ▾';q('.top').append(btn);q('.brand small').textContent='交互原型 · 未连接 AI';const mode=prototypeGlobal.document.createElement('div');mode.className='studio-mode-modal';mode.hidden=true;mode.innerHTML='<section role="dialog" aria-modal="true" aria-label="选择创作模式"><header><h3>你想怎样开始？</h3><button data-studio-dismiss>×</button></header><div><button data-studio-choose="quick"><strong>✦ 快速创作</strong><p>修改角色与设定，选一套美化模板，直接看作品效果。</p></button><button data-studio-choose="advanced"><strong>高级创作</strong><p>内容、自由画布、角色联动与 CSS，完整掌控作品。</p></button></div><small>两种模式共用一份数据，切换不会丢失修改。</small></section>';r.append(mode);mode.hidden=false;}
r.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(b.hasAttribute('data-studio-mode'))q('.studio-mode-modal').hidden=false;if(b.hasAttribute('data-studio-dismiss'))q('.studio-mode-modal').hidden=true;if(d.studioChoose){q('.studio-mode-modal').hidden=true;setStudioMode(d.studioChoose);}if(d.wholeTheme){applyWholeTheme(d.wholeTheme);editor();sceneRefresh();toast('整套美化已应用，剧情、状态值和手动位置保留。');}if(d.quickStep!==prototypeGlobal.undefined){studioStep=+d.quickStep;editor();preview();}if(b.hasAttribute('data-quick-next')){if(studioStep<3){studioStep++;editor();preview();}else setStudioMode('advanced');}if(b.hasAttribute('data-quick-prev')){studioStep=prototypeGlobal.Math.max(0,studioStep-1);editor();preview();}if(d.quickGen){q('#ps-agent-input').value=d.quickGen==='cover'?'根据当前作品设定生成 3:4 封面':'根据角色设定生成 3:4 立绘';psAssistant.classList.add('ai-expanded');q('#ps-agent-result').textContent='生图接口尚未接入。可以修改生成描述，或直接上传图片；不会把占位图标记为生成成功。';}if(d.linkRole){studioLink.roleId=prototypeGlobal.Number(d.linkRole);editor();preview();}if(b.hasAttribute('data-open-role-library'))go(8);if(d.linkTest){if(d.linkTest==='hit')stTestValues[studioLink.variable]=prototypeGlobal.Number(studioLink.threshold);else delete stTestValues[studioLink.variable];stCheckRules();sceneRefresh();runLinkAudio();toast(studioLink.enabled?'已更新测试状态，作品初始值不变。':'先打开「状态变化」开关，才会应用联动效果。');}if(b.hasAttribute('data-link-audio-start')){if(!studioLink.normalMusic&&!studioLink.activeMusic){toast('请先上传音频。');return;}studioRuntime.playing=true;if(studioLink.normalMusic){bgm.url=studioLink.normalMusic;baseAudio.src=bgm.url;audioSession=true;resumeBase();}runLinkAudio();}if(b.hasAttribute('data-link-audio-stop')){studioRuntime.playing=false;studioRuntime.lastHit=false;stopAudio();}if(b.hasAttribute('data-linked-speak')){if(!prototypeGlobal.window.speechSynthesis){toast('此浏览器不支持语音朗读。');return;}const u=new prototypeGlobal.SpeechSynthesisUtterance('邮戳是昨天的，可这座灯塔，已经废弃十年了。');u.lang='zh-CN';u.rate=linkagePass()&&studioLink.effects.tts?studioLink.activeRate:studioLink.rate;const voice=prototypeGlobal.speechSynthesis.getVoices().find(v=>v.name===studioLink.voice);if(voice)u.voice=voice;prototypeGlobal.speechSynthesis.cancel();prototypeGlobal.speechSynthesis.speak(u);}if(b.hasAttribute('data-apply-css'))applyManagedCSS(q('[data-managed-css]').value);if(b.hasAttribute('data-add-role-canvas')){const url=linkedImage();if(!url){toast('先在角色立绘中上传图片，再添加到画布。');return;}stAddDecoration('rect',url);sceneDesign.decorations.at(-1).name=(linkedRole()?.name||'角色')+' · 立绘';sceneDesign.decorations.at(-1).roleId=studioLink.roleId;sceneRefresh();}if(b.hasAttribute('data-studio-apply')&&studioProposal){const p=studioProposal;sceneRemember();if(p.theme)applyWholeTheme(p.theme,false);else if(p.description){quickRole().description=(quickRole().description||'')+'\n'+p.input;}else data['系统提示词']=(data['系统提示词']||'')+'\n'+p.input;studioProposal=null;editor();preview();q('#ps-agent-result').textContent='本地建议已应用，你可以继续修改。';}if(b.hasAttribute('data-studio-cancel')){studioProposal=null;q('#ps-agent-result').textContent='已取消，原内容保留。';}if(b.hasAttribute('data-quick-save')){const a=prototypeGlobal.document.createElement('a');a.href=prototypeGlobal.URL.createObjectURL(new prototypeGlobal.Blob([prototypeGlobal.JSON.stringify({data,roles,world,zones,sceneDesign,studioLink},null,2)],{type:'application/json'}));a.download='peach-work.json';a.click();prototypeGlobal.setTimeout(()=>prototypeGlobal.URL.revokeObjectURL(a.href),5000);}},false);
r.addEventListener('input',e=>{const t=e.target;if(t.dataset.quickRole){const role=quickRole();if(role)role[t.dataset.quickRole]=t.value;preview();}if(t.dataset.zoneQuick){zones.find(z=>prototypeGlobal.String(z.id)===t.dataset.zoneQuick).text=t.value;preview();}if(t.dataset.link){studioLink[t.dataset.link]=t.type==='checkbox'?t.checked:t.type==='number'?prototypeGlobal.Number(t.value):t.value;sceneRefresh();runLinkAudio();}if(t.dataset.linkEffect){studioLink.effects[t.dataset.linkEffect]=t.checked;sceneRefresh();runLinkAudio();}},false);
r.addEventListener('change',e=>{const t=e.target;if(t.hasAttribute('data-phone-independent')){studioMobileIndependent=t.checked;editor();sceneRefresh();}if(t.dataset.linkAudio&&t.files?.[0]){studioLink[t.dataset.linkAudio]=prototypeGlobal.URL.createObjectURL(t.files[0]);editor();}if(t.dataset.linkUpload&&t.files?.[0]){const key=(linkedRole()?.name||'角色')+' · '+t.files[0].name;images[key]=prototypeGlobal.URL.createObjectURL(t.files[0]);studioLink[t.dataset.linkUpload]=key;editor();sceneRefresh();}if(t.hasAttribute('data-quick-portrait')&&t.files?.[0]){const role=quickRole();const p={id:nextId++,url:prototypeGlobal.URL.createObjectURL(t.files[0]),name:t.files[0].name};role.pictures.push(p);role.defaultId=p.id;images[role.name+' · '+p.name]=p.url;editor();preview();}},false);
app.addEventListener('click',e=>{if(e.target.closest('[data-act="agent-send"]')){e.preventDefault();e.stopPropagation();studioOffer();}},true);
app.addEventListener('change',e=>{if(studioMode==='quick'&&e.target.id==='ps-mobile-nav'){e.stopPropagation();studioStep=prototypeGlobal.Number(e.target.value);editor();preview();}},true);
function visualTarget(t){const z=zones.find(z=>prototypeGlobal.String(z.id)===t.dataset.visualZone),f=z?.fields?.find(f=>f.id===t.dataset.visualField);return{z,f};}
function refreshContentSamples(){r.querySelectorAll('[data-field-sample]').forEach(el=>{const[zone,field]=el.dataset.fieldSample.split(':'),z=zones.find(z=>prototypeGlobal.String(z.id)===zone),f=z?.fields?.find(f=>f.id===field);if(f)el.innerHTML=presentationField(z,f);});}
function refreshVisualEditors(){editor();sceneRefresh();if(skinTarget)skinDialog();}
r.addEventListener('change',e=>{const t=e.target;if(t.hasAttribute('data-visual-mode')){const{z,f}=visualTarget(t);if(!f)return;sceneRemember();f.presentation=t.value;f.visual||={};if(t.value==='stars'||t.value==='hearts'){f.visual.glyph=t.value==='stars'?'★':'♥';delete f.visual.filledImage;delete f.visual.emptyImage;}sceneOpened=prototypeGlobal.String(z.id);refreshVisualEditors();}if(t.dataset.visualUpload&&t.files?.[0]){const{z,f}=visualTarget(t);if(!f)return;sceneRemember();f.visual||={};const reader=new prototypeGlobal.FileReader();reader.onload=()=>{f.visual[t.dataset.visualUpload]=reader.result;images[t.files[0].name+' · '+nextId++]=reader.result;refreshVisualEditors();};reader.readAsDataURL(t.files[0]);}},true);
r.addEventListener('focusin',e=>{if(e.target.hasAttribute('data-visual-prop'))sceneRemember();});
r.addEventListener('input',e=>{const t=e.target;if(t.dataset.visualProp){const{f}=visualTarget(t);if(!f)return;f.visual||={};const key=t.dataset.visualProp,limits={count:[1,30],size:[12,96],gap:[0,32]};f.visual[key]=limits[key]?stClamp(prototypeGlobal.Number(t.value)||limits[key][0],...limits[key]):t.value;sceneRefresh();refreshContentSamples();}if(t.dataset.statusValue||t.dataset.presentationRange||t.dataset.stTest)refreshContentSamples();});
r.addEventListener('click',e=>{const t=e.target.closest('[data-visual-remove]');if(!t)return;const{f}=visualTarget(t);if(!f)return;sceneRemember();delete f.visual[t.dataset.visualRemove];refreshVisualEditors();});
let ocFocus=null,ocSelected=[],ocTool='select',ocGesture=null,ocGuides=[],ocFrame=null;
function ocZone(){return zones.find(z=>z.id===ocFocus);}
function ocDoc(z=ocZone()){return z?.contentCanvas;}
function svLegacySources(){return zones.flatMap(z=>(z.fields||[]).map(f=>({id:z.id+':'+f.id,name:statusFieldName(z,f),value:stTestValues[z.id+':'+f.id]??f.value,min:f.min??0,max:f.max??100})));}
function ocNode(type,props={}){return{id:'element-'+nextId++,type,name:type==='text'?'文字':type==='image'?'图片':'图形',x:40,y:40,w:type==='text'?230:100,h:type==='text'?40:100,text:'双击修改文字',fill:'#ce678b',color:'#523d4a',fontSize:20,radius:12,opacity:100,rotation:0,rules:[],...props};}
function ocValue(node){
const sources=ocSources(),state={...node,clipX:100,clipY:100,scale:1,visible:!node.hidden,vars:{}};
if(node.origin){const[zone,field]=node.origin.split(':'),f=zones.find(z=>prototypeGlobal.String(z.id)===zone)?.fields?.find(f=>f.id===field);if(f?.visible===false)state.visible=false;}
for(const rule of node.rules||[]){const s=sources.find(s=>s.id===rule.source),raw=prototypeGlobal.Number(s?.value),a=prototypeGlobal.Number(rule.min??0),b=prototypeGlobal.Number(rule.max??100);if(!s||!prototypeGlobal.Number.isFinite(raw)||b<=a)continue;const progress=stClamp((raw-a)/(b-a),0,1),from=prototypeGlobal.Number(rule.from??0),to=prototypeGlobal.Number(rule.to??100),v=from+(to-from)*progress;
if(rule.property==='fillX')state.clipX=stClamp(v,0,100);else if(rule.property==='fillY')state.clipY=stClamp(v,0,100);else if(rule.property==='scale')state.scale=prototypeGlobal.Math.max(0,v)/100;else if(rule.property==='visible')state.visible=state.visible&&raw>=prototypeGlobal.Number(rule.threshold??rule.min??0);else if(rule.property==='variable'&&/^--[\w-]+$/.test(rule.variable||'--value'))state.vars[rule.variable||'--value']=v;else if(['x','y','w','h','rotation','opacity','fontSize','radius'].includes(rule.property))state[rule.property]=v;
}
const src=sources.find(s=>s.id===node.source);state.content=(node.text||'').replaceAll('{{value}}',src?prototypeGlobal.String(src.value):'—');return state;
}
function ocRender(z,editing=false){
const c=ocDoc(z);if(!c)return'';const selected=new prototypeGlobal.Set(ocSelected);
return`<div class="oc-surface ${editing?'oc-editing':''}" ${editing?'id="oc-stage"':''} data-oc-zone="${z.id}" style="aspect-ratio:${c.width}/${c.height};--oc-width:${c.width}px;--oc-height:${c.height}px">${c.nodes.map((n,index)=>{
const v=ocValue(n),p=ocProgress(n),sel=editing&&selected.has(n.id),geometry=`left:${v.x/c.width*100}%;top:${v.y/c.height*100}%;width:${prototypeGlobal.Math.max(2,v.w)/c.width*100}%;height:${prototypeGlobal.Math.max(2,v.h)/c.height*100}%;transform:rotate(${v.rotation||0}deg) scale(${v.scale});z-index:${n.layer??index+1};transform-origin:${(n.anchor?.x??.5)*100}% ${(n.anchor?.y??.5)*100}%;${!v.visible?editing?'opacity:.22;':'visibility:hidden;':''}`;
const art=p?`<div class="oc-progress-base">${ocArtwork(n,v,c.width,p.off)}</div><div class="oc-progress-fill" data-oc-fill="${p.pct}" style="clip-path:inset(0 ${100-p.pct}% 0 0)">${ocArtwork(n,v,c.width,p.on)}</div>`:ocArtwork(n,v,c.width);
return`<div class="oc-element ${sel?'oc-selected':''}" data-oc-node="${n.id}" style="${geometry}" ${p?`role="meter" aria-label="${esc(p.name)}" aria-valuemin="${p.min}" aria-valuemax="${p.max}" aria-valuenow="${stClamp(p.value,p.min,p.max)}"`:''}><div class="oc-visible-part" style="clip-path:inset(${100-v.clipY}% ${100-v.clipX}% 0 0)">${art}</div>${editing&&sel?`<span class="oc-element-label">${esc(n.name)}</span>${ocSelected.length===1&&!n.locked?['nw','ne','se','sw'].map(h=>`<span data-oc-handle="${h}" class="oc-handle ${h}"></span>`).join(''):''}`:''}</div>`;
}).join('')}${editing?ocGuides.map(g=>`<i class="oc-guide ${g.axis}" style="${g.axis==='x'?'left':'top'}:${g.value/(g.axis==='x'?c.width:c.height)*100}%"></i>`).join(''):''}</div>`;
}
