function am100Cards(list){return `<div class="am100-grid">${list.map(a=>`<article class="am100-card ${a.form==='sequence'?'is-effect':''}"><button type="button" data-am100-preview="${a.id}" class="am100-thumb" aria-label="预览${esc(a.name)}"><img src="${esc(a.thumbnail||a.url)}" alt="${esc(a.name)}" loading="lazy" decoding="async"><span class="am100-badge">${a.form==='sequence'?'▶ 动态 · 透明底':'查看大图'}</span></button><div class="am100-info"><div><h3>${esc(a.name)}</h3><span>${esc(a.materialGroup)}</span></div><small>${a.form==='sequence'?(a.sequence?.frames?.length||0)+' 帧 · 循环播放':a.width+' × '+a.height}</small></div><footer><button type="button" data-am100-add="${a.id}" ${a.used?'disabled':''}>${a.used?'已加入作品':'+ 加入本作品'}</button><button type="button" data-am100-use="${a.id}">${a.form==='sequence'?'放入画布':'设为背景'} ${svIcon('arrow-up-right')}</button></footer></article>`).join('')||'<p class="am100-empty">没有找到匹配的素材，试试其他关键词。</p>'}</div>`;}
