function am100Preview(id){
 const a=njAsset(id);if(!a)return;const state=am100State();state.preview=id;state.playing=true;state.background=false;
 svModal(a.name,`<div class="am100-preview ${a.form==='sequence'?'is-effect':''}"><div class="am100-preview-stage" data-am100-stage><img data-am100-player src="${esc(a.url)}" alt="${esc(a.name)}"></div><div class="am100-preview-meta"><span>${esc(a.materialGroup)} · ${a.width} × ${a.height}${a.form==='sequence'?' · 透明底':''}</span>${a.form==='sequence'?'<div><button type="button" data-am100-pause>暂停播放</button><button type="button" data-am100-backdrop>叠加场景查看</button></div>':''}</div><p>${a.form==='sequence'?'放入画布后可调整大小、位置、透明度、循环和播放速度；在「效果设计 → 提示词设置 → 播放特效 → 我的特效」中也可选择这份素材。':'设为背景会应用于当前作品的对话画面；选择「作为场景控件」可自由调整位置和尺寸。'}</p></div>`,`<button type="button" data-sv-close>关闭</button><button type="button" data-am100-add="${a.id}" ${a.used?'disabled':''}>${a.used?'已加入本作品':'加入本作品'}</button>${a.form==='image'?`<button type="button" data-am100-control="${a.id}">作为场景控件</button>`:''}<button type="button" class="solid" data-am100-use="${a.id}">${a.form==='sequence'?'放入画布':'设为当前背景'}</button>`);
 q('#sv-modal')?.classList.add('am100-modal');
 if(a.form==='sequence'){
  const img=q('[data-am100-player]');let frame=0;const play=()=>{if(!img?.isConnected||state.preview!==id)return;if(state.playing){img.src=a.sequence.frames[frame%a.sequence.frames.length];frame++;}prototypeGlobal.setTimeout(play,1000/(a.sequence.fps||12));};play();
 }
}
function am100Add(a){if(!a)return false;if(!nj.created){toast('请先创建或打开作品，再加入素材。','warning');return false;}a.used=true;njSyncAssetImages();njDirty();njSave(false);for(const b of r.querySelectorAll('[data-am100-add]'))if(b.dataset.am100Add===a.id){b.disabled=true;b.textContent='已加入本作品';}toast('已加入本作品，可在背景、序列帧和提示词素材选择中使用。','success');return true;}
function am100Use(a,control=false){
 if(!a)return false;
 if(!nj.created){toast('请先创建或打开作品，再使用素材。','warning');return false;}
 // Apply first, then let the existing draft scheduler save one final state.
 // am100Add used to serialize the full work before this function serialized it again.
 a.used=true;njSyncAssetImages();svClose();nj.previewAsset=null;
 if(a.form==='sequence'||control){go(12);kind='chat';return v129CreateComponent(a.form==='sequence'?'sequence':'background',a,a.name);}
 sceneRemember();
 const store=v64BackgroundStore(),item=store.items.find(x=>prototypeGlobal.String(x.id)===prototypeGlobal.String(store.activeId))||store.items[0];
 v64AppendBackground(item,[a]);const picture=item.pictures.find(p=>p.url===a.url);if(!picture)return false;
 item.defaultId=picture.id;store.activeId=item.id;v64SyncBackground();kind='chat';njDirty();editor();preview();toast('已设为当前作品的对话背景。','success');return true;
}
function am100Init(){
 if(am100Init.ready)return;am100Init.ready=true;
 prototypeGlobal.window.addEventListener('click',e=>{
  const b=e.target.closest?.('[data-am100-tab],[data-am100-group],[data-am100-preview],[data-am100-add],[data-am100-use],[data-am100-control],[data-am100-pause],[data-am100-backdrop]');if(!b||!r.contains(b))return;e.preventDefault();e.stopImmediatePropagation();const d=b.dataset,state=am100State();
  if(d.am100Tab){state.kind=['scenes','effects'].includes(d.am100Tab)?d.am100Tab:'';state.group='全部';state.query='';v148.library=d.am100Tab==='controls';nj.previewAsset=null;editor();wbIcons();return;}
  if(d.am100Group){state.group=d.am100Group;editor();wbIcons();return;}
  if(d.am100Preview)return am100Preview(d.am100Preview);
  if(d.am100Add)return am100Add(njAsset(d.am100Add));
  if(d.am100Use)return am100Use(njAsset(d.am100Use));
  if(d.am100Control)return am100Use(njAsset(d.am100Control),true);
  if(b.hasAttribute('data-am100-pause')){state.playing=!state.playing;b.textContent=state.playing?'暂停播放':'继续播放';return;}
  if(b.hasAttribute('data-am100-backdrop')){state.background=!state.background;const stage=q('[data-am100-stage]'),scene=am100List('scenes')[10]||am100List('scenes')[0];if(stage){stage.style.backgroundImage=state.background&&scene?'url("'+scene.url+'")':'';stage.classList.toggle('with-scene',state.background);}b.textContent=state.background?'查看透明底':'叠加场景查看';}
 },true);
 prototypeGlobal.window.addEventListener('input',e=>{if(e.target.matches?.('[data-am100-search]')){e.stopImmediatePropagation();am100Search(e.target.value);}},true);
}

function v130DefaultCatalog(){
 if(v130DefaultCatalog.items)return v130DefaultCatalog.items;
 const result=[],put=(id,name,category,type,url,width,height,extra={})=>result.push({id:'builtin-v130-'+id,key:'默认素材 · '+name,name,category,form:'image',project:'builtin',builtin:true,componentTypes:[type],url,width,height,used:false,version:1,...extra});
 const palettes=[['暮色紫',['#40354f','#211c32','#ae93cc','#f2e7ff']],['樱花粉',['#f5dce7','#e6b9cf','#c1779c','#582d4b']],['羊皮纸',['#fbefda','#dfc5a0','#aa8554','#503a2b']],['科技蓝',['#263e60','#121e34','#79bada','#e0f2ff']]];
 palettes.forEach(([name,palette],i)=>{for(const type of ['status','button'])put(type+'-'+i,name+' · '+(type==='status'?'状态入口':'操作按钮'),'UI',type,v130Skin(palette,type),480,type==='status'?128:112,{componentStyle:{textColor:palette[3],look:'clear'}});});
 const portraits=nj.assets.filter(a=>!a.builtin&&a.form==='image'&&a.category==='角色立绘'&&a.url).slice(0,3);
 portraits.forEach((a,i)=>put('portrait-'+i,a.name.replace(/ · 示例|（演示立绘）/g,''),'角色立绘','portrait',a.url,a.width,a.height));
 if(v72DefaultPortrait&&!portraits.some(a=>a.url===v72DefaultPortrait))put('portrait-galgame','少女 · 日常立绘','角色立绘','portrait',v72DefaultPortrait);
 const harbor=nj.assets.find(a=>a.form==='image'&&!a.builtin&&['远景','场景背景'].includes(a.category)&&!a.url.startsWith('data:image/svg'))||{url:v82GalgameBackground};
 if(harbor)put('background-harbor','海港 · 暮色街景','远景','background',harbor.url,harbor.width,harbor.height);
 put('background-room','夜色 · 窗边客厅','远景','background',v130Room(),1280,720);
 put('background-garden','春日 · 桃花小径','远景','background',v130Garden(),1280,720);
 for(const [kind,name] of [['halo','呼吸光环'],['sparkles','星光闪烁'],['petals','花瓣飘落']]){const frames=prototypeGlobal.Array.from({length:16},(_,i)=>v130Motion(kind,i,16));put('sequence-'+kind,name,'UI','sequence',frames[0],480,480,{form:'sequence',sequence:{id:'builtin-v130-seq-'+kind,name,frames,fps:8,loop:true,frameIndex:0,playing:false}});}
 return v130DefaultCatalog.items=result.concat(am100Catalog(),pt199Catalog(),am210Catalog());
}
function v130EnsureDefaults(){
 if(!nj.seed)return;
 const ids=new prototypeGlobal.Map(nj.assets.flatMap(a=>[[a.id,a],...(a.builtinId?[[a.builtinId,a]]:[])]));
 for(const item of v130DefaultCatalog()){
  if(ids.has(item.id))continue;
  // Reuse bundled artwork instead of duplicating large image data in every save.
  const existing=item.form==='image'&&nj.assets.find(a=>a.form==='image'&&a.url===item.url&&a.category===item.category);
  if(existing){existing.builtinSourceProject??=existing.project;prototypeGlobal.Object.assign(existing,{builtin:true,builtinId:item.id,project:'builtin',componentTypes:item.componentTypes.slice()});ids.set(item.id,existing);}
  else{const added=njClone(item);nj.assets.push(added);ids.set(item.id,added);}
 }
 // Restore only missing library records. Saved edits and used flags stay intact.
 for(const a of nj.assets.filter(a=>a.builtin)){
  if(!images[a.key])images[a.key]=a.url;
  sv.assetMeta[a.key]??={category:a.category,project:a.used?'本作品':'默认素材'};
  if(a.form==='sequence'&&!sv.sequences.some(s=>s.id===a.sequence.id))sv.sequences.push(njClone(a.sequence));
 }
}
function v130Recommended(type){v130EnsureDefaults();return nj.assets.filter(a=>a.builtin&&a.componentTypes?.includes(type));}
prototypeGlobal.window.addEventListener('click',e=>{
 const b=e.target.closest?.('[data-v130-defaults]');if(!b||!r.contains(b))return;e.preventDefault();e.stopImmediatePropagation();
 v130EnsureDefaults();
 if(b.dataset.v130Defaults==='picker'){if(!nj.picker)return;nj.picker.source='builtin';nj.picker.selected=null;njPickerRender();return;}
 nj.source='builtin';nj.selectedAsset=null;nj.previewAsset=null;editor();
},true);

function njInitAssets(){const seed=prototypeGlobal.JSON.parse(nj.seed.work),scene=prototypeGlobal.JSON.parse(seed.scene),seqs=scene.stateDesign.sequences;nj.assets=libraryEntries().map(([key,url],i)=>({id:'asset-'+(i+1),key,name:key.replace('（演示立绘）',''),url,category:svAssetCategory(key),form:'image',project:'sample-harbor',used:false,version:1}));
for(const seq of seqs)nj.assets.push({id:'asset-seq-'+seq.id,key:seq.name,name:seq.name,url:seq.frames[0],category:'角色立绘',form:'sequence',project:'sample-harbor',used:false,sequence:njClone(seq)});
const sceneSVG=(type)=>'data:image/svg+xml,'+prototypeGlobal.encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="720"><defs><linearGradient id="a" x2="0" y2="1"><stop stop-color="${type==='shop'?'#c7d3c7':'#819e97'}"/><stop offset="1" stop-color="${type==='shop'?'#fff1dc':'#dae1c3'}"/></linearGradient></defs><rect width="1280" height="720" fill="url(#a)"/>${type==='shop'?'<rect x="155" y="75" width="960" height="495" rx="18" fill="#fdf5e8"/><rect x="200" y="120" width="430" height="390" fill="#c3d7cb"/><path d="M415 120v390M200 315h430" stroke="#fdf5e8" stroke-width="18"/><rect x="100" y="535" width="1090" height="70" rx="8" fill="#bba18b"/><g fill="#d48e9a"><circle cx="840" cy="360" r="54"/><circle cx="900" cy="315" r="47"/><circle cx="956" cy="363" r="48"/></g><path d="M850 415h100l-15 125h-70z" fill="#eee1d5"/>':'<path d="M0 440L230 120 465 440 710 90 1015 430 1280 230V720H0" fill="#79968d"/><path d="M0 580Q520 300 1280 535V720H0" fill="#8daca0"/><path d="M800 720Q440 420 725 490L820 510Q600 500 1050 720" fill="#dacdaf"/><circle cx="1090" cy="120" r="52" fill="#f4e3ba"/>'}</svg>`);
for(const[name,cat,type]of[['花店窗边 · 示例','远景','shop'],['风原古林 · 示例','远景','forest'],['花店柜台 · 示例','中景','shop']])nj.assets.push({id:'asset-'+(nj.assets.length+1),key:name,name,url:sceneSVG(type)+(name.includes('柜台')?'#counter':''),category:cat,form:'image',project:'sample-flowers',used:false,version:1});v130EnsureDefaults();}
function auditBasenjProjectName(id){return id==='current'?(data['作品名称']||'本作品'):id==='sample-harbor'?'示例作品 · 雾港来信':id==='sample-flowers'?'示例作品 · 花间旅人':id;}
function njMatchAssets(source=nj.source,category=nj.category){v130EnsureDefaults();return nj.assets.filter(a=>(source==='all'||(source==='current'?a.used:a.project===source))&&(category==='全部类型'||category==='序列帧图'&&a.form==='sequence'||a.category===category));}
function njSyncAssetImages(){v130EnsureDefaults();for(const a of nj.assets){if(a.form==='video')continue;images[a.key]=a.url;sv.assetMeta[a.key]={category:a.category,project:a.used?'本作品':njProjectName(a.project)};if(a.form==='sequence'&&!sv.sequences.some(s=>s.id===a.sequence.id))sv.sequences.push(njClone(a.sequence));}}
