function njSourceOptions(value){return[['current','本作品'],['builtin','默认素材'],['all','全部素材'],...prototypeGlobal.Array.from(new prototypeGlobal.Set(nj.assets.map(a=>a.project))).filter(x=>x!=='current'&&x!=='builtin').map(x=>[x,njProjectName(x)])].map(([v,n])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(n)}</option>`).join('');}
function njTypeList(source,category,pick=false){return`<aside class="nj-type-list"><strong>素材类型</strong>${['全部类型','角色立绘','剧情画廊','远景','中景','序列帧图','UI'].map(c=>`<button ${pick?'data-nj-pick-category':'data-nj-category'}="${c}" class="${category===c?'on':''}" aria-pressed="${category===c}">${svIcon({'全部类型':'images','角色立绘':'user-round','剧情画廊':'gallery-horizontal','远景':'mountain','中景':'image','序列帧图':'film','UI':'panels-top-left'}[c])}<span>${c}</span><small>${njMatchAssets(source,c).length}</small></button>`).join('')}<p>远景：远处环境<br>中景：主体场景<br>序列帧：连续图片动画</p></aside>`;}
function v224BaseAssetCards(list,pick=false){return`<div class="nj-asset-grid">${list.map(a=>`<article ${['portraits199','anime210'].includes(a.materialPack)&&a.category==='角色立绘'?'data-portrait199':''} class="nj-asset-card ${nj.selectedAsset===a.id?'selected':''}"><button ${pick?'data-nj-pick-asset':'data-nj-asset'}="${a.id}"><div class="nj-asset-thumb ${a.category==='远景'||a.category==='中景'?'landscape':''}"><img src="${esc(a.thumbnail||a.url)}" loading="lazy" decoding="async" alt="${esc(a.name)}">${a.form==='sequence'?`<span>${svIcon('film')}${a.sequence.frames.length} 帧</span>`:''}</div><strong>${esc(a.name)}</strong><small>${esc(njProjectName(a.project))}</small></button><div class="nj-asset-foot"><span>${a.form==='sequence'?'序列帧 · ':''}${a.category}</span>${a.used?'<small class="nj-used">已在本作品</small>':pick?'<small>点击选择</small>':`<button data-nj-add-asset="${a.id}">加入本作品</button>`}</div></article>`).join('')||`<div class="nj-empty">${svIcon('images')}<strong>这里还没有素材</strong><p>上传图片，或从其他作品选择。</p><button ${pick?'data-nj-pick-all':'data-nj-all-sources'}>查看全部作品素材</button></div>`}</div>`;}
function vrLegacyAssetLibraryUI(){if(!nj?.ready)return njBaseAssetLibraryUI();const list=njMatchAssets();return`<div class="nj-material-workspace">${njTypeList(nj.source,nj.category)}<section class="nj-material-content"><div class="nj-material-toolbar"><label>素材来源<select data-nj-source>${njSourceOptions(nj.source)}</select></label><label class="nj-upload-link">${svIcon('upload')}${nj.category==='序列帧图'?'导入序列帧':'上传图片'}<input type="file" accept="image/*" multiple data-nj-upload hidden></label><button data-nj-image-dialog="material">${svIcon('sparkles')}AI 生成</button></div><div class="nj-material-subhead"><strong>${nj.category} <small>${list.length}</small></strong><div><button data-nj-library-tab="images" class="${nj.libraryTab!=='triggers'?'on':''}">素材</button><button data-nj-library-tab="triggers" class="${nj.libraryTab==='triggers'?'on':''}">图片触发</button></div></div>${nj.libraryTab==='triggers'?cgTriggerUI():nj.category==='序列帧图'?njSequenceCards(list):njAssetCards(list)}<p class="nj-material-note">本作品包含已上传、生成和调用的素材。序列帧也可归入角色立绘等用途，全部类型按独立素材计数。</p></section></div>`;}
