function vrResultPack(job=nj.job){if(!job)return njTake();if(job.type==='template')return job.result;const m=vrUnpack(job.base);for(const p of job.result.patches)vrWrite(m,p.target,p.value);return vrPack(m);}
function vrPending(){return nj.job&&['ready','generating','paused','failed','conflict'].includes(nj.job.status);}
function vrExample(){const id=nj.templateView||nj.selectedTemplate;if(!vr.examples[id]){const pack=njCompileTemplate(id,'');const m=vrUnpack(pack);m.s.zones.find(x=>x.id===4).enabled=true;m.s.design.backgroundRules=m.s.design.backgroundRules||[];vr.examples[id]=vrPack(m);}return nj.mode==='guided'?rxCharacterPack(vr.examples[id]):vr.examples[id];}
function vrCurrentPack(){if(vr.browse)return vrExample();if(vrPending())return vr.view==='before'?nj.job.base:vrResultPack();return njTake();}
