function c3BasevrResetExperience(){prototypeGlobal.clearTimeout(vr.previewTimer);vr.playing=false;vr.demoPlayers={};vr.session={step:0,opened:null,values:{},events:[],response:null};vr.chapter='story';}
function vrBegin(){if(nj.created){njConfirm('从这个范例重新开始','现有作品会保留在版本记录中。现在使用这份完整范例创建新草稿？',vrCreate,'创建新草稿');return;}vrCreate();}
function gxBasevrCreate(){const pack=njClone(vrExample()),before=njTake();njRestore(pack);nj.created=true;nj.job=null;nj.localTarget=null;nj.templateView=null;vr.browse=false;vr.view='after';nj.history.push({before,after:njTake(),title:'从完整范例创建草稿'});nj.history=nj.history.slice(-3);njAdoptTemplateAssets();nj.turns.push({role:'assistant',text:'作品已经可以体验了。下面几种调整都能直接点选，也可以先保持现在的样子。'});vrResetExperience();svClose();page=10;editor();preview();njSave(false);toast('草稿已创建。角色、故事、界面和素材都已准备好。','success');}
function vrDescribeRule(value,m){if(!value?.enabled)return'不使用这项变化';const f=m.s.stateDesign.defs.find(f=>f.id===value.variable),name=f?vrFieldName(f,m):'已有数值';return name+' '+({gte:'达到',gt:'超过',lt:'低于',lte:'不高于',eq:'等于',neq:'不等于'}[value.op]||'达到')+' '+value.threshold+' 时，'+(value.effect==='glow'?'气泡出现流光':value.effect==='shake'?'气泡轻轻晃动':'切换对应表现');}
function vrFieldName(f,m){const entity=id=>id==='player'?'玩家':m.w.roles.find(r=>'role:'+r.id===id)?.name||'';return(f.from?entity(f.from)+'对'+entity(f.to)+'的':f.owner?entity(f.owner)+'的':'')+f.name;}
function vrChoicePlan(choice,pack,scope=null){const m=vrUnpack(pack),role=m.w.roles.find(x=>scope?.type==='role'&&prototypeGlobal.String(x.id)===prototypeGlobal.String(scope.id))||m.w.roles[0],t=njTemplates.find(t=>t.id===nj.selectedTemplate)||njTemplate(),patches=[];const put=(target,value,label)=>{const before=njClone(vrRead(m,target));if(prototypeGlobal.JSON.stringify(before)!==prototypeGlobal.JSON.stringify(value)){patches.push({target,before,value,label});vrWrite(m,target,value);}};
if(['warm','slow'].includes(choice)&&role){const warm=choice==='warm',old=role.description||'',desc=warm?'会主动开启话题、关心玩家的处境，也保留自己的判断和边界。关系依靠真实相处建立，尊重玩家的选择。':'先观察、核实，再表达自己的判断。不会在刚见面时亲近玩家，信任通过共同经历和兑现约定慢慢建立。';put({type:'role',id:role.id,key:'description'},desc,'角色会怎样与你相处');const entry=m.w.world.find(x=>x.name.includes(role.name))||m.w.world.find(x=>x.category==='角色设定'&&role===m.w.roles[0]);if(entry)put({type:'world',id:entry.id,key:'text'},desc,'故事中的角色规则');const core=m.s.data['系统提示词']||'';put({type:'data',key:'系统提示词'},old&&core.includes(old)?core.replace(old,desc):core+'\n'+role.name+'：'+desc,'角色的回应依据');const z=m.s.zones.find(z=>z.id===2);if(z&&role===m.w.roles[0]){const paragraphs=z.text.split('\n');const i=paragraphs.findIndex(p=>/[“「"]/.test(p));paragraphs[i<0?2:i]=warm?'“你来了。先别着急，跟我说说你想怎么做，我们一起想办法。”':'“先等一下。我需要确认眼前的情况，再决定下一步。你怎么看？”';put({type:'zone',id:z.id,key:'text'},paragraphs.join('\n'),'现在这段对话');}}
else if(['paper','night'].includes(choice)){const night=choice==='night';put({type:'object',id:'2',key:'tint'},night?'#252a3a':'#fff5e7','正文气泡的底色');put({type:'object',id:'2',key:'radius'},night?14:28,'正文气泡的圆角');put({type:'data',key:'正文颜色'},night?'#f4edf2':'#594637','正文的颜色');put({type:'data',key:'对白颜色'},night?'#f6cbdf':'#a04c69','对白的颜色');for(const id of['10','4','5']){put({type:'object',id,key:'tint'},night?'#353244':'#fff5e7','状态按钮底色');put({type:'object',id,key:'textColor'},night?'#f4edf2':'#594637','状态按钮文字');}}
else if(choice==='brief'){const target=scope||{type:'data',key:'简介',label:'作品简介'},old=prototypeGlobal.String(vrRead(m,target)||'');put(target,old.split(/[。\n]/).filter(prototypeGlobal.Boolean).slice(0,2).join('。')+'。',target.label||'精简后的文字');}
else if(choice==='glow'){put({type:'object',id:'2',key:'rule'},{enabled:true,variable:'10:mood',op:'gte',threshold:80,effect:'glow',color:'#ed80ad',mode:'hold'},'心情与画面的变化');}
else if(choice==='opening'){const title=m.s.data['作品名称'];put({type:'data',key:'开场 HTML'},'<main style="min-height:100vh;display:grid;place-items:center;background:#242738;color:#f8e9db;font-family:sans-serif;text-align:center"><section><p style="letter-spacing:8px;color:#d6a5bd">一段属于你的故事</p><h1 style="font-size:48px">'+esc(title)+'</h1><p>'+esc(m.s.data['简介'])+'</p><button style="margin-top:24px;padding:14px 32px;border-radius:30px;border:0;background:#e75d8a;color:white">开始聊天</button></section></main>','进场页面');}
return{patches,summary:{warm:'角色会更主动地接近玩家，同时保留自己的边界。',slow:'角色会先观察，再慢慢建立信任。',paper:'画面换成温暖纸张的质感。',night:'画面换成安静的夜色，文字同步保持清晰。',brief:'文字已经精简，关键内容保留。',glow:'玩家心情达到 80 时，正文气泡会出现粉色流光。',opening:'进场页换成夜色风格，作品名称和简介自动沿用。'}[choice]||'内容已调整。'};}
function vrPropose(choice,text='',scope=null){if(nj.job?.status==='generating'){toast('正在准备效果，可以暂停后继续调整。');return;}vr.browse=false;vr.choice=choice;const prior=vrPending()?nj.job:null,base=prior?.base||njTake(),working=prior?vrResultPack(prior):base;let plan=choice?vrChoicePlan(choice,working,scope):vrInModel(working,()=>njTextPlan(scope,text));const patches=prior?.type==='patch'?njClone(prior.result.patches):[];for(const p of plan.patches){const existing=patches.find(x=>prototypeGlobal.JSON.stringify(x.target)===prototypeGlobal.JSON.stringify(p.target));if(existing)existing.value=p.value;else patches.push(p);}if(!patches.length){toast('当前内容已经是这个效果，可以直接继续创作。');return;}nj.job={id:nj.jobSerial++,type:'patch',idea:text||choice,scope,status:'generating',step:0,attempt:1,base,result:{patches,summary:plan.summary},steps:['结合已有角色与故事','呈现修改后的内容'],startedAt:prototypeGlobal.Date.now(),vrChoice:choice,vrViewed:false};nj.epoch++;vr.view='after';vrResetExperience();if(['warm','slow'].includes(choice))vr.session.step=2;if(choice==='opening')vr.chapter='opening';if(choice==='glow')vr.session.values['10:mood']=85;nj.turns.push({role:'user',text:text||({warm:'让她更主动一点',slow:'让她慢热一点',paper:'试试温暖的纸张风格',night:'试试安静的夜色',brief:'让文字简短一些',glow:'心情好时，让画面亮起来',opening:'试试夜色的进场页'}[choice]||'调整一下')});njPaint();njTick(nj.epoch);}
function njStart(type,idea='',scope=null){if(!vr.ready)return vrLegacyNjStart(type,idea,scope);if(type==='template'){vr.browse=true;vrBegin();return;}vrPropose(null,idea,scope);}
function njTick(epoch){if(!vr.ready)return vrLegacyNjTick(epoch);prototypeGlobal.clearTimeout(nj.timer);const j=nj.job;if(!j||j.status!=='generating'||nj.epoch!==epoch)return;nj.timer=prototypeGlobal.setTimeout(()=>{if(nj.epoch!==epoch||j!==nj.job||j.status!=='generating')return;if(nj.failNext){nj.failNext=false;njTransition('failed');njPaint();njSave(false);toast('演示中断：刚才的进度保留，可以继续。','warning');return;}j.step++;if(j.step>=j.steps.length){njTransition('ready');j.vrViewed=true;njPaint();if(vr.reviewModal)njShowPlan();njSave(false);toast(page===10?'候选效果已准备好，确认后才会替换原文。':'候选内容已准备好，请在页内对比并确认。','success');}else{njPaint();njTick(epoch);}},400);}
function njResume(){if(!vr.ready)return vrLegacyNjResume();if(nj.job?.status==='conflict'){const j=nj.job;nj.job=null;vrPropose(j.vrChoice,j.idea,j.scope);return;}if(njTransition('generating')){nj.epoch++;njPaint();njTick(nj.epoch);}}
function njApply(){if(!vr.ready)return vrLegacyNjApply();const j=nj.job;if(j?.status!=='ready')return;if(!j.vrViewed){njShowPlan();return;}const conflicts=j.result.patches.filter(p=>prototypeGlobal.JSON.stringify(njRead(p.target))!==prototypeGlobal.JSON.stringify(p.before));if(conflicts.length){njTransition('conflict');njPaint();toast('这部分内容刚被手动修改，请保留原稿或按最新内容再调整。','warning');return;}const before=njTake();for(const p of j.result.patches)njWrite(p.target,p.value);svEnsure();njTransition('applied');nj.history.push({before,after:njTake(),title:'保存这次调整'});nj.history=nj.history.slice(-3);nj.created=true;nj.localTarget=null;vr.view='after';vr.reviewModal=false;nj.turns.push({role:'assistant',text:'这次调整已保存到作品。可以继续看效果，也可以先保持这样。'});svClose();if(!ahRestore(j.result.patches)){editor();preview();}njSave(false);toast('已保存这次调整，原稿保留在版本记录中。','success');}
function njCancel(){if(!vr.ready)return vrLegacyNjCancel();if(nj.job)nj.job.status='cancelled';prototypeGlobal.clearTimeout(nj.timer);nj.epoch++;vrResetExperience();vr.reviewModal=false;nj.localTarget=null;svClose();if(!ahRestore()){editor();preview();}njSave(false);toast('已保留原来的作品。');}
function gxBasenjSave(notify=true){return njSave(notify);}
function vrBootstrap(){vr.ready=true;vr.browse=!nj.created;vrResetExperience();if(nj.job?.type==='template'&&nj.job.status==='ready'){nj.job=null;}for(const seq of sv.sequences)seq.playing=false;vrSyncMotion();editor();preview();}
function vrSuggestions(){return`<section class="vr-suggestions"><div class="vr-content-heading">${svIcon('sparkles')}不需要想好全部，先挑一个喜欢的效果</div><p>点选就能看到变化；不想改，可以先保持这样。</p><div class="vr-choice-pair"><button data-vr-choice="warm"><strong>让角色更主动一点</strong><span>“你来了。先别着急，我们一起想办法。”</span></button><button data-vr-choice="slow"><strong>让角色慢热一点</strong><span>“先等一下。我需要确认情况。你怎么看？”</span></button></div><div class="vr-choice-pair"><button data-vr-choice="paper"><i class="vr-style-sample paper">今天的故事，从这里开始。</i><strong>温暖的纸张</strong></button><button data-vr-choice="night"><i class="vr-style-sample night">今天的故事，从这里开始。</i><strong>安静的夜色</strong></button></div><div class="vr-keep-row"><button data-vr-keep>先保持这样，继续创作 ${svIcon('arrow-right')}</button><button data-vr-browse>再看看其他范例</button></div></section>`;}
function vrHumanValue(p,value,m){if(p.target.key==='开场 HTML'||/CSS/i.test(p.target.key))return`<div class="vr-visual-description">${svIcon('panels-top-left')}这是页面外观。${p.target.key==='开场 HTML'?'<button data-vr-chapter="opening">在右侧查看进场效果</button>':'请直接对照右侧实际画面。'}</div>`;if(p.target.type==='object'){if(p.target.key==='rule')return`<p>${esc(vrDescribeRule(value,m))}</p>`;if(/color|tint/i.test(p.target.key))return`<p class="vr-color-description"><i style="background:${esc(prototypeGlobal.String(value||'transparent'))}"></i>${p.target.key==='textColor'?'文字颜色':'背景颜色'} <span>${esc(prototypeGlobal.String(value||'跟随作品'))}</span></p>`;if(p.target.key==='radius')return`<p>圆角 ${prototypeGlobal.Number(value)||0} 像素</p>`;if(p.target.key==='opacity')return`<p>不透明度 ${prototypeGlobal.Number(value)}%</p>`;return`<p>外观已调整，请对照右侧画面。</p>`;}if(typeof value==='object')return'<p>关联设置已更新，可在右侧体验。</p>';const text=prototypeGlobal.String(value||'尚未填写');if(/<\/?(?:style|script|div|main|section|html|body)\b/i.test(text))return'<p>页面效果已更新，请在右侧查看。</p>';return`<p>${esc(text)}</p>`;}
function vrReview(){const j=nj.job;if(!j||j.type!=='patch')return'';const m=vrUnpack(vrResultPack(j)),original=vrUnpack(j.base),items=j.result.patches,isStyle=p=>p.target.type==='object'&&p.target.key!=='rule'||p.target.type==='data'&&/颜色/.test(p.target.key),styles=items.filter(isStyle),texts=items.filter(p=>!isStyle(p)&&!(p.target.type==='data'&&['系统提示词','前置词','后置词'].includes(p.target.key))&&p.target.type!=='world'),main=texts.length||styles.length?texts:items;
const sample=model=>{const obj=model.s.design.objects['2']||{},status=model.s.design.objects['10']||{},line=(model.s.zones.find(z=>z.id===2)?.text||'今天的故事，从这里开始。').split('\n')[0];return`<div class="vr-appearance-sample"><div style="background:${esc(obj.tint||'#fffaf7')};color:${esc(model.s.data['正文颜色']||'#423840')};border-radius:${prototypeGlobal.Math.min(prototypeGlobal.Number(obj.radius)||16,24)}px"><small>正文</small><p>${esc(line)}</p></div><span style="background:${esc(status.tint||'#fff7f9')};color:${esc(status.textColor||'#745d6a')}">人物状态 ›</span></div>`;};
return`<section class="vr-review"><div class="vr-review-top"><span>${svIcon('sparkles')}这次调整</span><small>原作品仍保留</small></div><h3>${esc(j.result.summary)}</h3><div class="vr-compare-switch"><button data-vr-view="before" class="${vr.view==='before'?'on':''}">原来的效果</button><button data-vr-view="after" class="${vr.view==='after'?'on':''}">调整后的效果</button></div>${styles.length?`<article class="vr-change"><strong>画面与文字一起调整</strong><div class="vr-readable-diff"><div><small>原来</small>${sample(original)}</div><div><small>调整后</small>${sample(m)}</div></div><p class="vr-note">右侧可以查看完整画面，正文和状态按钮已同步搭配。</p></article>`:''}${main.map(p=>`<article class="vr-change"><strong>${esc(p.label)}</strong><div class="vr-readable-diff"><div><small>原来</small>${vrHumanValue(p,p.before,m)}</div><div><small>调整后</small>${vrHumanValue(p,p.value,m)}</div></div></article>`).join('')}${items.some(p=>p.target.type==='world')?`<p class="vr-note">角色的回应依据与相关世界书已一起调整，保持同一份设定。</p>`:''}<div class="vr-review-actions"><button class="solid" data-vr-save-change>保存这次调整</button><button data-vr-discard>保持原来的作品</button></div><p class="vr-note">还不满意？下面继续点选，或直接说一句想改哪里。</p></section>`;}
