 const z={id:zoneId,name,kind:'status',enabled:true,statusEntry:true,fold:'收起',text:'',statusPanel:{version:1,presetId:spec.id,presetVersion255:1,title:spec.title,display:'pinned',fieldIds:fields.map(f=>f.id),blocks,progressField:map[spec.progress]||'',background:spec.background,ink:spec.ink,radius:spec.radius,skin:spec.id,recordLabel:spec.recordLabel,layouts:{}}};
