 if(model.errors.length)return {ok:false,error:model.errors.join('\n')};
 if(!model.entries.length)return {ok:false,error:'请至少关联一项状态，并启用状态更新提示词。'};
 const ui=v135UI(),session=v132Session(edit),id='state-'+prototypeGlobal.Date.now().toString(36)+'-'+(++ui.serial),signature=prototypeGlobal.JSON.stringify(model);
 const fields=model.entries.map(f=>({...f,current:v132Value(f.id,edit)}));
 const req={id,owner:data,session,work:c3Key(),edit,panelIds,signature,stamp:v135Stamp(session),fields,used:false};
 req.prompt=v135BuildPrompt(req,model.prompts);session.v135Latest=id;ui.requests.set(id,req);
 while(ui.requests.size>20)ui.requests.delete(ui.requests.keys().next().value);
