function hmCopy(){const t=njTemplates.find(x=>x.id===data['范例类型']);if(!t)return c2BasehmCopy();const timelines={mystery:'昨天：邮戳标注的寄信日。\n今天：玩家收到来信，与沈岚在灯塔外核对线索。\n接下来：由玩家选择先去邮局还是检查塔门。',companion:'傍晚：雨开始落下，花店准备收店。\n现在：你走进花店，沈栀邀请你坐一会儿。\n之后：不设强制路线，日常由对话慢慢展开。',adventure:'清晨：抵达古林边缘。\n现在：渡口钟声响起，洛岚发现脚印。\n下一步：询问航班，或先调查旧桥。',life:'周一 09:00：搬入梧桐路的新公寓。\n中午：程叙提出午饭邀请，是否赴约由你决定。\n未来：职业、生活与人际分支由行动逐步形成。',radio:'多年前：第七频道停播。\n23:58：异常录音被接收。\n明天零点：录音提到的时间，尚未成为事实。'};return{title:data['作品名称']||t.title,subtitle:data['简介']||t.summary,world:t.world,timeline:timelines[t.id],guide:'直接输入想说的话或想做的事。正文完整显示，长内容可在气泡内滚动。\n\n点击人物、记录、记忆或行动入口展开；再次点击同一入口或面板标题收起。\n\n行动建议不是限制，你可以随时自由回应。',author:'这是一个借鉴优秀作品组织方式的可编辑示例。你可以更改角色、世界书、开场与画面，让它成为自己的作品。',profile:'姓名\n成年身份\n来到这里的原因\n希望保留的个人背景',custom:'填写希望玩家看到的内容。'};}
function c3BasehmCreate(theme='archive'){const model=c2BasehmCreate(theme);model.design.homeVersion=3;for(const z of model.design.decorations){const p=z.position;if(z.id==='home-cover')prototypeGlobal.Object.assign(p,{x:5,y:7,w:36,h:520});else if(z.id==='home-eyebrow')prototypeGlobal.Object.assign(p,{x:46,y:12,w:48,h:35});else if(z.id==='home-title')prototypeGlobal.Object.assign(p,{x:46,y:23,w:48,h:95});else if(z.id==='home-intro')prototypeGlobal.Object.assign(p,{x:47,y:40,w:45,h:115});else if(z.id==='home-start')prototypeGlobal.Object.assign(p,{x:48,y:64,w:34,h:58});else if(z.homeComponent){p.y=86;p.h=56;}const a=model.design.objects[z.id];if(theme==='radio')a.radius=5;if(theme==='life')a.radius=18;}return model;}
