function c3Value(f){const v=c3Session().values[f.id]??f.initial;return f.type==='text'?prototypeGlobal.String(v??''):prototypeGlobal.Math.max(f.min??-prototypeGlobal.Infinity,prototypeGlobal.Math.min(f.max??prototypeGlobal.Infinity,prototypeGlobal.Number(v)||0));}
function fcNewField(name='',owner='玩家'){return{id:'value-'+prototypeGlobal.Date.now()+'-'+nextId++,name,owner,type:'number',initial:0,min:null,max:null,unit:'',enabled:true,description:'',rules:[]};}
function fcSamples(type){const f=fcNewField();if(type==='energy'){prototypeGlobal.Object.assign(f,{name:'精力',initial:30,min:0,max:30,unit:'点',description:'玩家精力上限30；行动消耗3—5；休息恢复10；充足睡眠恢复15。',rules:[{id:'e1',when:'行动,探索,调查',op:'subtract',amount:3,amountMax:5},{id:'e2',when:'休息,睡觉',op:'add',amount:10},{id:'e3',when:'充足睡眠,睡得很好',op:'add',amount:15}]});}else if(type==='gold'){prototypeGlobal.Object.assign(f,{name:'金币',initial:100,min:0,unit:'枚',description:'玩家有100枚金币；购买药水扣20；完成委托获得50。',rules:[{id:'g1',when:'购买药水',op:'subtract',amount:20},{id:'g2',when:'完成委托',op:'add',amount:50}]});}else if(type==='trust'){prototypeGlobal.Object.assign(f,{name:'信任',owner:(roles[0]?.name||'角色')+'对玩家',initial:30,min:0,max:100,description:'角色对玩家的信任初始30；兑现承诺增加5；违背承诺减少10。',rules:[{id:'t1',when:'兑现承诺',op:'add',amount:5},{id:'t2',when:'违背承诺',op:'subtract',amount:10}]});}else if(type==='task'){prototypeGlobal.Object.assign(f,{name:'任务阶段',owner:'当前任务',type:'text',initial:'未开始',description:'接受委托时变为进行中；交付证据时变为已完成。',rules:[{id:'q1',when:'接受委托',op:'set',value:'进行中'},{id:'q2',when:'交付证据',op:'set',value:'已完成'}]});}f.rules.forEach((r,i)=>r.id=f.id+'-'+i);return f;}
function c3RuleParse(text){const f=fcNewField();f.description=text;const names=text.match(/(?:添加|显示|记录)?(?:玩家(?:的)?|角色(?:的)?)?([\u4e00-\u9fa5A-Za-z]{2,8})(?:值)?(?:初始|上限|最大|为|是|：)/);f.name=names?.[1]?.replace(/^玩家(?:的)?/,'')||(/精力/.test(text)?'精力':/金币/.test(text)?'金币':/信任/.test(text)?'信任':/好感/.test(text)?'好感':/任务/.test(text)?'任务阶段':'自定义状态');if(/精力/.test(text)){prototypeGlobal.Object.assign(f,fcSamples('energy'));f.description=text;}const rel=text.match(/([\u4e00-\u9fa5]{1,6})对([\u4e00-\u9fa5]{1,6})的/);if(rel)f.owner=rel[1]+'对'+rel[2];const initial=text.match(/(?:初始(?:值)?|开始(?:是|为)?|起始)(?:为|是|：|\s)*(\d+(?:\.\d+)?)/),max=text.match(/(?:上限|最大(?:值|精力|体力)?)(?:为|是|：|\s)*(\d+(?:\.\d+)?)/);if(initial)f.initial=prototypeGlobal.Number(initial[1]);if(max){f.max=prototypeGlobal.Number(max[1]);if(!initial)f.initial=f.max;f.min=0;}
const parts=text.split(/[；;。\n]/).map(x=>x.trim()).filter(prototypeGlobal.Boolean),parsed=[];for(const part of parts){const m=part.match(/(?:当|每次)?(.{1,22}?)(?:时|后)?(?:会|可)?(?:消耗|扣除|扣|减少|降低|增加|获得|恢复|回复)\s*(\d+(?:\.\d+)?)(?:\s*[-—~至到]\s*(\d+(?:\.\d+)?))?/);if(m){const op=/消耗|扣|减少|降低/.test(m[0])?'subtract':'add',when=m[1].replace(/^(?:并且|且|每次)/,'').replace(/(?:时|后)$/,'').trim();if(when)parsed.push({id:'rule-'+nextId++,when,op,amount:prototypeGlobal.Number(m[2]),...(m[3]?{amountMax:prototypeGlobal.Number(m[3])}:{})});}const v=part.match(/(?:当)?(.{1,20}?)(?:时|后)(?:变为|变成|设为|是)(.+)/);if(v){f.type='text';f.initial=typeof f.initial==='string'?f.initial:'未开始';parsed.push({id:'rule-'+nextId++,when:v[1],op:'set',value:v[2].trim()});}}
if(parsed.length)f.rules=parsed;return f;}
function c3RuleOpen(zone=null,text=''){if(vr.browse&&nj.created){njConfirm('把想法用于当前范例？','将从这个范例创建草稿，当前作品保留在版本记录中。',()=>{vrCreate();c3RuleOpen(zone,text)},'继续');return;}if(!nj.created)vrCreate();const z=zones.find(z=>prototypeGlobal.String(z.id)===prototypeGlobal.String(zone));fc.proposal={zone:z?.id||null,fields:z?fcFields(z).map(f=>njClone(fcMigrateField(f))):[],idea:text||'',existing:!!z};if(text)fc.proposal.fields=[c3RuleParse(text)];c3RuleDialog();}
function fcRuleText(rule,f){return'当「'+rule.when+'」发生时，'+({add:'增加 ',subtract:'减少 ',set:'变为 '}[rule.op])+(rule.op==='set'?rule.value:rule.amount+(rule.amountMax>rule.amount?'～'+rule.amountMax:''))+(f.type==='text'?'':f.unit||'');}
function fcFieldCard(f,i){return`<details class="fc-value-card" data-fc-value-card="${f.id}" open><summary><strong>${esc(f.owner||'归属未填')} · ${esc(f.name||'新内容')}</strong><span>${f.type==='text'?'文字':'数值'}</span></summary><div class="fc-value-edit"><div class="pr-field-grid"><label>内容名称<input data-fc-field="name" data-i="${i}" value="${esc(f.name)}" placeholder="例如：心情、金币、任务阶段"></label><label>属于谁 / 谁对谁<input data-fc-field="owner" data-i="${i}" value="${esc(f.owner)}" placeholder="例如：林晚对玩家"></label><label>内容类型<select data-fc-field="type" data-i="${i}"><option value="number" ${f.type!=='text'?'selected':''}>数值</option><option value="text" ${f.type==='text'?'selected':''}>文字 / 阶段</option></select></label><label>初始内容<input data-fc-field="initial" data-i="${i}" type="${f.type==='text'?'text':'number'}" value="${esc(f.initial)}"></label></div>${f.type!=='text'?`<details class="fc-range"><summary>范围与单位（可选）</summary><div class="pr-field-grid">${[['min','最小值'],['max','最大值'],['unit','单位']].map(([k,n])=>`<label>${n}<input data-fc-field="${k}" data-i="${i}" ${k==='unit'?'':'type="number"'} value="${f[k]??''}" placeholder="${k==='unit'?'可留空':'不限制'}"></label>`).join('')}</div></details>`:''}<div class="fc-rules"><header><strong>什么时候变化</strong><small>同次回复按顺序执行；同一关键词不重复结算</small></header>${(f.rules||[]).map((r,j)=>`<div class="fc-rule-row"><label>发生什么<input data-fc-rule="when" data-i="${i}" data-j="${j}" value="${esc(r.when)}" placeholder="例：完成委托"></label><label>怎样改变<select data-fc-rule="op" data-i="${i}" data-j="${j}">${(f.type==='text'?[['set','变为']]:[['add','增加'],['subtract','减少'],['set','设为']]).map(([v,n])=>`<option value="${v}" ${r.op===v?'selected':''}>${n}</option>`).join('')}</select></label><label>内容<input data-fc-rule="${r.op==='set'?'value':'amount'}" data-i="${i}" data-j="${j}" value="${esc(r.op==='set'?r.value??'':r.amount??0)}" ${f.type==='text'?'':'type="number"'}></label><button data-fc-rule-remove="${i}:${j}" aria-label="删除这条变化">${svIcon('x')}</button></div>`).join('')}<button data-fc-rule-add="${i}">＋ 添加变化规则</button></div><button data-fc-field-remove="${i}" class="fc-danger">移除这项内容</button></div></details>`;}
function c3RuleDialog(){const p=fc.proposal;svModal('可变化的内容',`<p class="fc-value-intro">每项内容都可以有自己的归属、初始内容与多条变化规则；一个状态栏可以展示多项。</p><div class="fc-idea-input"><textarea data-fc-idea rows="2" placeholder="也可以直接描述：玩家金币初始100；购买药水减少20；完成委托增加50。">${esc(p.idea)}</textarea><button data-fc-parse>${svIcon('sparkles')}整理为规则</button></div><div class="fc-example-chips"><span>试一个例子</span>${[['energy','精力'],['gold','金币'],['trust','关系'],['task','任务阶段']].map(([v,n])=>`<button data-fc-value-example="${v}">${n}</button>`).join('')}</div><div class="fc-value-fields">${p.fields.map(fcFieldCard).join('')||'<div class="fc-empty-state">这里可以是任何你需要记录的内容。选一个例子修改，或直接添加。</div>'}</div><button class="fc-wide-add" data-fc-value-add>＋ 添加另一项内容</button><p class="fc-value-error" role="alert"></p><small class="pr-note">离线演示将保存的事件词作为变化依据。自由描述由本地规则解析，采用前可直接检查、修改；没有连接在线 AI。</small>`,'<button data-sv-close>取消</button><button class="solid" data-c3-rule-apply>保存并显示</button>');q('#sv-modal').classList.add('fc-values-modal');}
function c3ApplyRule(){const p=fc.proposal,err=q('.fc-value-error');if(!p?.fields.length){err.textContent='请先添加至少一项内容。';return;}const names=new prototypeGlobal.Set();for(const f of p.fields){const key=f.owner.trim()+'·'+f.name.trim();if(!f.name.trim()||!f.owner.trim()||names.has(key)){err.textContent='每项请填写名称与归属，同一归属下名称不重复。';return;}names.add(key);if(f.type==='number'&&(!prototypeGlobal.Number.isFinite(prototypeGlobal.Number(f.initial))||f.min!=null&&f.max!=null&&f.max<=f.min||f.min!=null&&f.initial<f.min||f.max!=null&&f.initial>f.max)){err.textContent='请检查「'+f.name+'」的范围与初始值。';return;}if(f.rules.some(r=>!r.when.trim()||r.op!=='set'&&(!prototypeGlobal.Number.isFinite(prototypeGlobal.Number(r.amount))||r.amount<0))){err.textContent='请补齐「'+f.name+'」的变化条件与内容。';return;}}
sceneRemember();const ids=[];for(const f of p.fields){const old=c3Defs().find(x=>x.id===f.id)||c3Defs().find(x=>x.name===f.name&&x.owner===f.owner);if(old){f.id=old.id;prototypeGlobal.Object.assign(old,njClone(f));}else c3Defs().push(njClone(f));ids.push(f.id);}let z=zones.find(z=>prototypeGlobal.String(z.id)===prototypeGlobal.String(p.zone));if(!z){z={id:nextId++,name:p.fields.length===1?p.fields[0].owner+' · '+p.fields[0].name:'我的状态',enabled:true,kind:'status',text:''};zones.push(z);}z.valueIds=ids;delete z.metricId;z.metricView??='number';sceneSettings(prototypeGlobal.String(z.id)).placement='free';const t=fcStyles[fcThemeId()]||fcStyles.archive;prototypeGlobal.Object.assign(sceneSettings(prototypeGlobal.String(z.id)),{tint:t.card,textColor:t.ink,opacity:100});fc.proposal=null;svClose();sv.uiTab='canvas';go(12);udSelect(z.id);stOpen(prototypeGlobal.String(z.id),false);ceMount(true);njDirty();toast('内容与规则已保存，可在右侧查看并体验变化。','success');}
function fcValueHTML(f,view,z){const v=c3Value(f),hasRange=f.type!=='text'&&f.min!=null&&f.max!=null&&f.max>f.min,pct=hasRange?stClamp((v-f.min)/(f.max-f.min)*100,0,100):null,color=sceneSettings(prototypeGlobal.String(z.id)).textColor||c3Theme().accent;return`<div class="fc-value-display" data-fc-value="${f.id}" style="--meter-color:${color};--meter-pct:${pct||0}%"><div><span class="art193-value-title">${art193Icon(art193Key(f.name,'gem'))}${esc(f.owner)} · ${esc(f.name)}</span><strong>${esc(v)}<small>${esc(f.unit||'')}${hasRange?' / '+f.max:''}</small></strong></div>${hasRange&&view==='bar'?`<div class="c3-meter-track"><span style="width:${pct}%"></span></div>`:hasRange&&view==='ring'?`<div class="c3-meter-ring"><span>${prototypeGlobal.Math.round(pct)}<small>%</small></span></div>`:hasRange&&view==='image'?`<div class="c3-picture-meter">${z.metricImage?`<img src="${esc(z.metricImage)}" alt="${esc(f.name)}"><div style="clip-path:inset(0 ${100-pct}% 0 0)"><img src="${esc(z.metricImage)}" alt=""></div>`:`<span class="c3-stars">★★★★★<b style="width:${pct}%">★★★★★</b></span>`}</div>`:''}</div>`;}
function c3MetricHTML(z){return`<div class="fc-values-display">${fcFields(z).map(f=>fcValueHTML(f,z.valueViews?.[f.id]||z.metricView||'number',z)).join('')}</div>`;}
function c3MetricEditor(z){const fields=fcFields(z);return`<label class="pr-label">状态栏标题<input data-ud-name value="${esc(z.name)}"></label><button class="fc-edit-values" data-c3-rule-open="${z.id}">${svIcon('sparkles')}编辑内容与变化规则</button><p class="pr-note">这块状态栏中有 ${fields.length} 项内容，显示方式可分别选择。</p>${fields.map(f=>`<div class="fc-value-inspector"><strong>${esc(f.owner)} · ${esc(f.name)}</strong><label>展示方式<select data-fc-view="${f.id}" data-zone="${z.id}">${(f.type==='text'||f.min==null||f.max==null?[['number','文字 / 数字']]:[['number','数字'],['bar','进度条'],['ring','百分比圆环'],['image','整张图案填充']]).map(([v,n])=>`<option value="${v}" ${(z.valueViews?.[f.id]||z.metricView||'number')===v?'selected':''}>${n}</option>`).join('')}</select></label>${fcValueHTML(f,z.valueViews?.[f.id]||z.metricView||'number',z)}<small>${(fcMigrateField(f).rules||[]).map(r=>esc(fcRuleText(r,f))).join('<br>')||'尚未设置自动变化，可继续告诉助手。'}</small></div>`).join('')}${fields.some(f=>(z.valueViews?.[f.id]||z.metricView)==='image')?`<label class="c3-upload">上传自己的完整图案<input type="file" accept="image/*" data-c3-metric-file="${z.id}"></label>`:''}<details class="fc-rule-test" open><summary>体验一次变化</summary><select data-fc-event-choice>${fields.flatMap(f=>fcMigrateField(f).rules.map(rule=>`<option value="${esc(rule.when.split(/[,，]/)[0])}">${esc(rule.when)}</option>`)).join('')}</select><button data-fc-run-event>发生这件事</button><button data-fc-reset>回到初始内容</button><div class="fc-event-result">${c3Session().events.slice(-3).map(e=>`<p>${esc(e.summary)}</p>`).join('')}</div></details>`;}
function c3ApplyEvent(event){const s=c3Session();if(s.done.has(event.id))return[];s.done.add(event.id);const text=event.text||event.kind||'',matched=[];for(const f of c3Defs().filter(f=>f.enabled!==false&&(!event.field||f.id===event.field))){const rules=fcMigrateField(f).rules||[];const candidates=rules.map(r=>({r,keys:r.when.split(/[,，]/).map(k=>k.trim()).filter(k=>k&&text.includes(k))})).filter(x=>x.keys.length);const keep=candidates.filter(x=>!candidates.some(y=>y!==x&&y.keys.some(a=>x.keys.some(b=>a!==b&&a.includes(b)))));for(const{r}of keep)matched.push({f,r});}const pending=new prototypeGlobal.Map(),logs=[];for(const{f,r}of matched){const before=pending.has(f.id)?pending.get(f.id):c3Value(f);let value=before;if(f.type==='text')value=prototypeGlobal.String(r.value||'');else{let n=prototypeGlobal.Number(r.amount)||0;if(r.amountMax>n)n+=s.events.filter(x=>x.rule===r.id).length%(r.amountMax-n+1);if(r.op==='subtract'&&f.min!=null&&before-n<f.min){const log={field:f.id,kind:'blocked',before,after:before,summary:f.owner+'的'+f.name+'不足，事件未执行，其他内容也不改变。'};s.events.push(log);return[log];}value=r.op==='set'?prototypeGlobal.Number(r.value)||0:r.op==='subtract'?before-n:before+n;if(f.min!=null)value=prototypeGlobal.Math.max(f.min,value);if(f.max!=null)value=prototypeGlobal.Math.min(f.max,value);}pending.set(f.id,value);logs.push({id:event.id,rule:r.id,field:f.id,kind:'change',before,after:value,summary:f.owner+' · '+f.name+'：'+before+' → '+value+'（'+r.when+'）'});}for(const[k,v]of pending)s.values[k]=v;s.events.push(...logs);for(const log of logs)if(log.before!==log.after)v152Emit('state:'+log.field,'change',log.after,log.before);return logs;}
function v70BaseSendLocal(value){const logs=c3ApplyEvent({id:'turn-'+prototypeGlobal.Date.now()+'-'+c3.serial++,text:value}),s=c3Session(),t=njTemplates.find(t=>t.id===data['范例类型']);const reply=logs.some(x=>x.kind==='blocked')?'这次行动暂未执行。请先恢复所需的状态。':t?c2Response({...t,role:roles[0]?.name||t.role,entry:world.find(w=>w.name==='开局场景')?.text||t.entry},value):'已记录这次输入。自由续写需要连接 AI。';s.turns.push({user:value,reply:reply+(logs.length?'\n\n'+logs.map(x=>x.summary).join('\n'):'')});rx.chatDraft='';const input=q('#rx-player-input');if(input)input.value='';c3Refresh();prototypeGlobal.requestAnimationFrame(()=>{const el=q('#ps-screen .fc-prose-scroll');if(el)el.scrollTop=el.scrollHeight;});}
function osBaseagentConversationSend(message){const text=prototypeGlobal.String(message??q('#ps-agent-input')?.value??'').trim();if(/数值|状态|精力|金币|信任|好感|任务阶段|初始|增加|减少|消耗|变为/.test(text)){if(q('#ps-agent-input'))q('#ps-agent-input').value='';c3RuleOpen(null,text);return;}return c3BaseagentConversationSend(message);}
function osBaseudAddMenu(){fuAddMenu();}
prototypeGlobal.window.addEventListener('click',e=>{const b=e.target.closest('[data-fc-value-example],[data-fc-value-add],[data-fc-parse],[data-fc-field-remove],[data-fc-rule-add],[data-fc-rule-remove],[data-fc-run-event],[data-fc-reset]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const d=b.dataset,p=fc.proposal;if(d.fcValueExample){p.fields.push(fcSamples(d.fcValueExample));c3RuleDialog();}else if(b.hasAttribute('data-fc-value-add')){p.fields.push(fcNewField());c3RuleDialog();}else if(b.hasAttribute('data-fc-parse')){const text=q('[data-fc-idea]').value.trim();if(!text){q('.fc-value-error').textContent='可以先选一个例子，或描述你想记录什么。';return;}p.idea=text;p.fields.push(c3RuleParse(text));c3RuleDialog();}else if(d.fcFieldRemove!==prototypeGlobal.undefined){p.fields.splice(prototypeGlobal.Number(d.fcFieldRemove),1);c3RuleDialog();}else if(d.fcRuleAdd!==prototypeGlobal.undefined){p.fields[prototypeGlobal.Number(d.fcRuleAdd)].rules.push({id:'rule-'+nextId++,when:'',op:p.fields[prototypeGlobal.Number(d.fcRuleAdd)].type==='text'?'set':'add',amount:1,value:''});c3RuleDialog();}else if(d.fcRuleRemove){const[i,j]=d.fcRuleRemove.split(':').map(prototypeGlobal.Number);p.fields[i].rules.splice(j,1);c3RuleDialog();}else if(b.hasAttribute('data-fc-run-event')){const text=q('[data-fc-event-choice]')?.value;if(!text){toast('先添加一条变化规则。');return;}const logs=c3ApplyEvent({id:'test-'+prototypeGlobal.Date.now()+'-'+c3.serial++,text});c3Refresh();toast(logs.map(x=>x.summary).join('；')||'没有匹配的规则。',logs.some(x=>x.kind==='blocked')?'warning':'success');}else if(b.hasAttribute('data-fc-reset')){delete c3.sessions[c3Key()];c3Refresh();}},true);
prototypeGlobal.window.addEventListener('input',e=>{const el=e.target,p=fc.proposal;if(!p)return;if(el.hasAttribute('data-fc-idea'))p.idea=el.value;if(el.dataset.fcField){const f=p.fields[prototypeGlobal.Number(el.dataset.i)],k=el.dataset.fcField;if(['min','max'].includes(k))f[k]=el.value===''?null:prototypeGlobal.Number(el.value);else if(k==='initial')f.initial=f.type==='text'?el.value:prototypeGlobal.Number(el.value);else f[k]=el.value;}if(el.dataset.fcRule){const f=p.fields[prototypeGlobal.Number(el.dataset.i)],r=f.rules[prototypeGlobal.Number(el.dataset.j)],k=el.dataset.fcRule;r[k]=k==='amount'?prototypeGlobal.Number(el.value):el.value;if(k==='amount')delete r.amountMax;}},true);
prototypeGlobal.window.addEventListener('change',e=>{const el=e.target,p=fc.proposal;if(el.dataset.fcField==='type'){const f=p.fields[prototypeGlobal.Number(el.dataset.i)];f.type=el.value;f.initial=f.type==='text'?'未开始':0;f.rules=[];c3RuleDialog();}if(el.dataset.fcRule==='op'){p.fields[prototypeGlobal.Number(el.dataset.i)].rules[prototypeGlobal.Number(el.dataset.j)].op=el.value;c3RuleDialog();}if(el.dataset.fcView){const z=stFind(el.dataset.zone);sceneRemember();z.valueViews??={};z.valueViews[el.dataset.fcView]=el.value;c3Refresh();njDirty();}},true);
function v11BasePanel(id){const p=fcBasec2PanelLayout(id),z=stFind(id);if(!z||!fcFields(z).length)return p;const H=stHeight(),height=64+fcFields(z).reduce((n,f)=>n+((z.valueViews?.[f.id]||z.metricView)==='ring'?145:82),0),a=sceneSettings(id),o=sceneLayout(id);p.h=prototypeGlobal.Math.min(H-140,height);const mode=a.openMode||'auto';if(mode==='up'||mode==='auto'&&(p.y/100*H+p.h>H-100))p.y=prototypeGlobal.Math.max(4,o.y-(p.h+10)/H*100);return c2Limit('open-'+id,p);}
