function bliss193Apply(plan){const story=zones.find(z=>prototypeGlobal.Number(z.id)===2);if(story&&!story.richContent&&!story.contentCanvas&&(plan.mode==='ai'||/(?:开场白|故事开场|开场)\s*[:：]/.test(plan.source?.core||'')))v185Owned(story,'text',plan.spec.opening);v185Music(plan);sv.layouts[sv.mode]=sceneDesign.layouts.pc;plan.report.styleName='极乐速递 · 玫瑰来信';plan.report.components=[{name:'来信正文',count:1},{name:'自定义状态栏',count:4},{name:'关联状态',count:c3Defs().length},{name:'信使立绘',count:1},{name:'行动选项',count:1}];plan.report.stateCount=c3Defs().length;data['内容生成设计']={version:193,mode:plan.mode,styleName:plan.report.styleName,generatedAt:new prototypeGlobal.Date().toISOString(),report:plan.report};njDirty();return plan.report;}

