function rfRefine(design,list,shortcuts=[]){
 if(design.templateLayoutRevision===2)return;
 const bliss=design.theme==='c2-bliss-express193';
 if(!bliss&&design.theme!=='c2-world-atlas193')return;
 const builtin=new prototypeGlobal.Set(bliss?['bliss-215005','bliss-215007','bliss-215014','bliss-215015','bliss-215016','bliss-215018','bliss-215024','bliss-215025','bliss-215030']:['atlas-193922','atlas-193935','atlas-193951','atlas-193953','atlas-193964']);
 const removed=new prototypeGlobal.Set();
 for(const z of list){if(!z.statusPanel)continue;z.statusPanel.blocks=z.statusPanel.blocks.filter(b=>{if(b.type==='button'&&builtin.has(b.id)){removed.add('block:'+z.id+'/'+b.id);return false;}return true;});z.statusPanel.simpleHeading=true;}
 if(design.interactions){design.interactions.rules=(design.interactions.rules||[]).filter(r=>!removed.has(r.source));design.interactions.managed=(design.interactions.managed||[]).filter(id=>!removed.has(id));}
 const shortcutIds=new prototypeGlobal.Set(bliss?[215201,215202,215203]:[193001,193002,193003]);
 for(let i=shortcuts.length-1;i>=0;i--)if(shortcutIds.has(shortcuts[i].id))shortcuts.splice(i,1);
 const cfg=design.flowLayout??=rfDefault(design,list);
 cfg.variant=bliss?'correspondence':'field-journal';
 if(cfg.maxWidth===1080)cfg.maxWidth=bliss?1080:1120;
 const action=cfg.groups.find(g=>g.id==='actions'),status=cfg.groups.find(g=>g.id==='status');
 if(action&&status&&cfg.groups.indexOf(action)>cfg.groups.indexOf(status)){cfg.groups=cfg.groups.filter(g=>g!==action);cfg.groups.splice(cfg.groups.indexOf(status),0,action);}
 if(bliss){const portrait=cfg.items['bliss-portrait'];if(portrait&&portrait.width===72){portrait.width='full';delete portrait.unit;}}
 else for(const id of status?.items||[]){if(cfg.items[id]?.width==='full')cfg.items[id].width=50;}
 design.templateLayoutRevision=2;
}

