    if(normalized!==null&&env.supports&&(!key.startsWith('--')||selector==='.player-input-theme')&&!env.supports(selector==='.player-input-theme'?'color':key,normalized))normalized=null;
    if(normalized===null){warn(original+' → '+key,'该属性或写法暂不能可靠同步；已保留在待处理清单，未默默取数字替代。',declaration.trim());continue;}
