 clone.querySelectorAll('script,iframe,object,embed,audio,video').forEach(x=>x.remove());
 for(const el of [clone,...clone.querySelectorAll('*')]){for(const attr of [...el.attributes])if(attr.name.startsWith('on'))el.removeAttribute(attr.name);el.removeAttribute('contenteditable');el.removeAttribute('autofocus');el.removeAttribute('tabindex');}
