function v67PaintPreview(){const s=v67CSS.session,frame=q('#v67-style-preview');if(!s||!frame)return;const width=frame.clientWidth||260;frame.style.height=(width*s.height/s.width)+'px';frame.srcdoc=v67PreviewDoc(s,s.preview==='after',width);}
