function v67InputCSSUI(){return `<section class="global-css-section rp-canvas-css"><header class="global-section-heading"><div class="v110-help-label"><h4>内置 CSS</h4>${v104Explain('css')}</div></header><div class="v67-dock-tools"><label>${svIcon('upload')}导入 CSS<input type="file" accept=".css,.txt,text/css,text/plain" data-v67-import aria-label="导入 CSS 文件"></label><button data-v67-action="open">${svIcon('sparkles')}AI 帮我调整</button>${v67CSS.last?'<button data-v67-action="undo">撤销上次应用</button>':''}${data['CSS调整记录']?.length?'<button data-v67-action="history">调整记录</button>':''}<small>导入或点「应用」，先检查再同步</small></div><div class="global-code-surface"><textarea class="code" data-managed-css aria-label="内置 CSS" spellcheck="false">${esc(rp.cssDraft??managedCSS())}</textarea></div><div class="global-css-footer"><p id="managed-css-status" role="status">${esc(rp.cssStatus)}</p><button data-apply-css>${svIcon('check')}应用</button></div><p class="global-css-note">修改先保留为草稿。确认采用后，才同步到画布与实时预览。</p></section>`;}
