/* Original script 17: inline */

(() => {
  const initialize = () => {
    prototypeGlobal.globalThis.lucide?.createIcons({ attrs: { width: 16, height: 16 } });
  };
  if (prototypeGlobal.globalThis.lucide != null) {
    initialize();
    return;
  }
  prototypeGlobal.document
    .getElementById("codex-visualization-lucide")
    ?.addEventListener("load", initialize, { once: true });
})();



/* Original script 18: v158-hover-behavior */

(()=>{
 const cardOf=target=>target?.closest?.('.v157-template-card');
 const enter=event=>{const card=cardOf(event.target);if(!card)return;if(event.relatedTarget instanceof prototypeGlobal.Node&&card.contains(event.relatedTarget))return;card.classList.add('v157-hovered');};
 const leave=event=>{const card=cardOf(event.target);if(!card)return;if(event.relatedTarget instanceof prototypeGlobal.Node&&card.contains(event.relatedTarget))return;card.classList.remove('v157-hovered');};
 prototypeGlobal.window.addEventListener('pointerover',enter,true);prototypeGlobal.window.addEventListener('pointerout',leave,true);
 prototypeGlobal.window.addEventListener('mouseover',enter,true);prototypeGlobal.window.addEventListener('mouseout',leave,true);
 prototypeGlobal.window.addEventListener('focusin',event=>cardOf(event.target)?.classList.add('v157-hovered'),true);
 prototypeGlobal.window.addEventListener('focusout',event=>{const card=cardOf(event.target);if(card&&!card.contains(event.relatedTarget))card.classList.remove('v157-hovered');},true);
})();



/* Original script 19: v160-hover-scroll-behavior */

(()=>{
  const scrollOf=target=>target?.closest?.('.v159-hover-scroll');
  prototypeGlobal.window.addEventListener('wheel',event=>{
    const scroll=scrollOf(event.target);
    if(!scroll || scroll.scrollHeight<=scroll.clientHeight) return;
    const before=scroll.scrollTop;
    scroll.scrollTop+=event.deltaY;
    if(scroll.scrollTop!==before){event.preventDefault();event.stopPropagation();}
  },{capture:true,passive:false});
})();



/* Original script 20: v165-hover-preview-state */

(()=>{
 let idleTimer=0;
 const cardOf=target=>target?.closest?.('.v157-template-card');
 const inPreview=target=>!!target?.closest?.('#v151-preview-pane,.right');
 const cancelIdle=()=>{if(idleTimer){prototypeGlobal.clearTimeout(idleTimer);idleTimer=0;}};
 const scheduleIdle=()=>{cancelIdle();idleTimer=prototypeGlobal.setTimeout(()=>{idleTimer=0;prototypeGlobal.window.v165HoverPreview?.(null);},110);};
 const entered=event=>{
  const card=cardOf(event.target);
  if(card){
   if(event.relatedTarget instanceof prototypeGlobal.Node&&card.contains(event.relatedTarget))return;
   cancelIdle();
   const id=card.querySelector('[data-os-pick]')?.dataset?.osPick;
   if(id)prototypeGlobal.window.v165HoverPreview?.(id);
   return;
  }
  if(inPreview(event.target))cancelIdle();
 };
 const left=event=>{
  const card=cardOf(event.target);
  if(!card)return;
  if(event.relatedTarget instanceof prototypeGlobal.Node&&(card.contains(event.relatedTarget)||cardOf(event.relatedTarget)||inPreview(event.relatedTarget)))return;
  scheduleIdle();
 };
 prototypeGlobal.window.addEventListener('pointerover',entered,true);
 prototypeGlobal.window.addEventListener('pointerout',left,true);
 prototypeGlobal.window.addEventListener('pointerover',event=>{if(inPreview(event.target))cancelIdle();},true);
 prototypeGlobal.window.addEventListener('focusin',event=>{
  const card=cardOf(event.target);
  if(card){cancelIdle();const id=card.querySelector('[data-os-pick]')?.dataset?.osPick;if(id)prototypeGlobal.window.v165HoverPreview?.(id);}
  else if(inPreview(event.target))cancelIdle();
 },true);
 prototypeGlobal.window.addEventListener('focusout',event=>{
  const card=cardOf(event.target);
  if(card&&!(card.contains(event.relatedTarget)||cardOf(event.relatedTarget)||inPreview(event.relatedTarget)))scheduleIdle();
 },true);
 prototypeGlobal.window.addEventListener('click',event=>{if(event.target.closest?.('[data-v156-use],[data-os-pick],[data-os-import]'))cancelIdle();},true);
})();



/* Original script 21: v166-demo-toolbar */

(()=>{
 let current=null,paused=false;
 const bar=()=>prototypeGlobal.document.querySelector('#v151-preview-pane #v166-demo-bar');
 const paint=()=>{const b=bar();if(!b)return;b.querySelector('[data-v166-status]').textContent=paused?'已暂停':'自动播放 · 无需操作';b.querySelector('[data-v166-pause]').textContent=paused?'继续播放':'暂停';};
 const mount=()=>{
  if(!current||!prototypeGlobal.document.body.contains(prototypeGlobal.document.querySelector('#v151-preview-pane')))return;
  const head=prototypeGlobal.document.querySelector('#v151-preview-pane .previewhead');
  if(!head||bar())return;
  const b=prototypeGlobal.document.createElement('div');
  b.id='v166-demo-bar';
  b.innerHTML='<strong>实例演示</strong><span data-v166-status>自动播放 · 无需操作</span><button type="button" data-v166-pause>暂停</button><button type="button" data-v166-replay>重新播放</button>';
  head.append(b);paint();
 };
 prototypeGlobal.window.v166StartDemo=id=>{
  if(!id)return;current=id;paused=false;mount();paint();
 };
 prototypeGlobal.window.v166StopDemo=()=>{current=null;paused=false;bar()?.remove();};
 const pane=prototypeGlobal.document.querySelector('#v151-preview-pane');
 if(pane)new prototypeGlobal.MutationObserver(()=>{if(current&&!paused)mount();}).observe(pane,{childList:true,subtree:true});
 prototypeGlobal.window.addEventListener('click',e=>{const pause=e.target.closest?.('[data-v166-pause]'),replay=e.target.closest?.('[data-v166-replay]');if(pause){paused=!paused;prototypeGlobal.window.v166DemoControl?.(paused?'pause':'resume');paint();}if(replay&&current){paused=false;prototypeGlobal.window.v166DemoControl?.('replay');paint();}},true);
})();


